window.BANK={"id": "m1", "title": "Mock Exam #1", "minutes": 120, "mode": "practice", "v": 1, "items": [{"id": "s6-04", "type": "single", "skill": "S6 · Security and Compliance", "stem": "Customer files and a stream land in bronze tables in Unity Catalog, and new columns with personal data appear unpredictably. Compliance wants them found and masked for most users, with no job able to bypass it. Assume classification and ABAC are enabled (check the docs for their release status). Which design fits?", "options": ["Write raw data to a separate storage account and grant the privacy team access only to that location through an external location", "Add a masking step inside each batch and streaming job that hashes every column it believes holds personal data, coded by that team", "Enable data classification on the catalog so detected columns get governed tags, and attach an ABAC mask policy to the tags", "Ask each team to review new columns weekly and apply column masks manually when they find personal data, tracked in a ticket"], "answer": 2, "runner": 1, "runnerWhy": "masking inside the job wins when the raw value must never be written to storage at all, such as when landing storage is out of compliance scope.", "think": {"premise": "That masking belongs in pipeline code. A control on the governed table covers every writer, while code covers only the job that contains it.", "map": [["Unknown new PII columns", "Automatic classification and tags", "Detect, then tag"], ["Many writers, batch and streaming", "Control on the Unity Catalog table", "Policy follows the table"], ["Raw value must never be stored", "Mask before landing", "In-pipeline masking wins"]], "apply": [["\"appear unpredictably\"", "Needs automatic detection, not a fixed column list."], ["\"no job able to bypass it\"", "Rules out per-job masking and manual review."], ["\"Customer files and a stream\"", "Table-level policy covers both write paths."]], "rule": "Detect with classification, protect with a tag-based policy on the table, and every writer is covered.", "guide": "Implement a compliant data pipeline that enforces PII detection and masking controls across batch and streaming workloads using Unity Catalog features."}, "eli5": "A guard at the warehouse door checks every box, whichever truck delivered it, instead of trusting each driver to remember.", "learn": "https://docs.databricks.com/aws/en/data-governance/unity-catalog/data-classification", "why": ["Works, but it restricts a location and does not detect personal data or mask it in the governed tables.", "Works, but only that job is covered, and the logic depends on the job guessing the right columns.", "Best fit: classification finds new columns and the tag-based policy protects them regardless of which job wrote them.", "Works, but weekly manual review leaves unmasked personal data exposed between reviews."]}, {"id": "s7-03", "type": "single", "skill": "S7 · Data Governance", "stem": "A governance team tags columns pii = true. Teams keep writing their own versions such as yes or Y. The team wants the platform itself to reject any value except true or false, and to let only a small approved group set it. Which kind of tag fits?", "options": ["A table property set with TBLPROPERTIES on each table, checked by a weekly script", "A governed tag whose tag policy lists the two values, assignable only by the approved group", "A column comment saying the column holds personal data, edited by the column owners", "A plain tag, with a written naming convention and preferred values shared with all teams"], "answer": 1, "runner": 3, "runnerWhy": "plain tags are fine and easiest when spellings need not be enforced and anyone with APPLY TAG may assign them.", "think": {"premise": "That every tag is equally controlled. Governed tags enforce permitted keys and values and restrict who may assign them.", "map": [["Teams invent spellings", "Uncontrolled plain tags", "Use a governed tag with a tag policy"], ["Only some people may set it", "Governed tag permission", "Grant that permission to the approved group"], ["Free labels, no enforcement needed", "Plain tags", "Plain tag wins"]], "apply": [["\"reject any value except true or false\"", "Needs enforcement by the platform, not a convention."], ["\"let only a small approved group set it\"", "Needs controlled assignment, which plain tags do not give."]], "rule": "When tags must be controlled, make them governed.", "guide": "Demonstrate understanding of Unity Catalog tags and comments as mechanisms for adding metadata to securable objects to improve data discoverability."}, "eli5": "A plain tag is a sticker anyone can write on; a governed tag is a printed label only the approved person can stick on.", "learn": "https://docs.databricks.com/aws/en/database-objects/tags", "why": ["Works, but table properties are enforced only by a script run after the fact.", "Best fit: governed tags enforce their permitted values and limit who can assign them.", "Works, but comments are free text, neither enforced nor usable as tag-based policy input.", "Works, but a convention is not enforced, so spellings drift again."]}, {"id": "s6-05", "type": "single", "skill": "S6 · Security and Compliance", "stem": "Following an erasure request, an engineer ran DELETE on a Delta table that has deletion vectors enabled, and a count for that customer returns zero. Legal now requires that the data is physically gone from storage, including older table versions. What should the engineer do next?", "options": ["Replace the customer's values with a hash using UPDATE, then keep the table history as it is", "Run VACUUM only, since it removes every deleted row from the current data files", "Run OPTIMIZE on the table, since compaction always rewrites every file that contains deleted rows", "Run REORG TABLE with APPLY (PURGE) to rewrite the affected files, then run VACUUM once the retention period allows"], "answer": 3, "runner": 2, "runnerWhy": "OPTIMIZE rewrites many files and may apply soft deletes, but the docs say it does not guarantee that every recorded change is applied; PURGE does.", "think": {"premise": "That DELETE erases data. With deletion vectors it only marks rows, and old file versions stay readable until they are rewritten and vacuumed.", "map": [["Row marked deleted, file untouched", "Deletion vector soft delete", "REORG TABLE APPLY (PURGE)"], ["Old versions readable by time travel", "Unreferenced files still in storage", "VACUUM after retention"], ["Law accepts pseudonymization", "Replacement instead of deletion", "UPDATE with hash can win"]], "apply": [["\"deletion vectors enabled\"", "DELETE only marked the rows."], ["\"physically gone from storage\"", "Needs rewrite plus VACUUM."], ["\"including older table versions\"", "Rules out UPDATE that leaves history."]], "rule": "DELETE hides, PURGE rewrites, VACUUM removes; erasure needs all three.", "guide": "Implement a data purging strategy that satisfies data retention and deletion policies (e.g., GDPR right-to-erasure, GDPR right-to-be-forgotten deletion) using Delta Lake and Unity Catalog features."}, "eli5": "Crossing a name off a list does not shred the old copies of the list that are still in the cabinet.", "learn": "https://docs.databricks.com/aws/en/delta/deletion-vectors", "why": ["Works, but the original values stay readable in history, and hashing is pseudonymization, not erasure.", "Works, but VACUUM alone leaves soft-deleted rows in current files, since it removes only unreferenced files.", "Works, but compaction is not guaranteed to apply every recorded delete, and it leaves old versions in place.", "Best fit: PURGE rewrites files with soft-deleted rows, and VACUUM then removes the older versions."]}, {"id": "s5-05", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A silver table receives updates and deletes from a source system. The gold table must apply only the changed rows each hour, including deletes, and a full rescan of the source is too slow. What should the team do on the silver table?", "options": ["Enable Change Data Feed and read its changes into the gold merge", "Compare the latest version with the previous one using time travel and a join", "Read the silver table as a stream with default options and append to gold", "Add a last-modified column to silver and filter on that column each hour"], "answer": 0, "runner": 1, "runnerWhy": "a modified-time filter is cheap, but it misses deletes; it wins if the source never deletes rows.", "think": {"premise": "That an incremental read always sees deletes. A plain stream and a timestamp filter do not.", "map": [["Updates and deletes must propagate", "Row-level changes", "Change Data Feed"], ["Append-only source", "Simple stream", "Plain streaming read"], ["No deletes ever", "Timestamp filter", "Last-modified column"]], "apply": [["\"including deletes\"", "A timestamp filter cannot see a row that no longer exists."], ["\"full rescan ... too slow\"", "Rules out the version-compare join."]], "rule": "To pass on deletes without rescanning, read the change feed.", "guide": "Apply Change Data Feed (CDF) to expose row-level changes (updates/deletes) for efficient incremental downstream processing."}, "eli5": "Reading the changes list stapled to a ledger instead of recounting every page.", "learn": "https://docs.databricks.com/aws/en/delta/delta-change-data-feed", "why": ["Best fit: CDF returns inserts, update before and after images and deletes with commit versions.", "Works, but it reads both versions in full, which is the rescan the team wants to avoid.", "Works, but a default stream of a table with updates or deletes fails or ignores the changes and does not carry deletes.", "Works, but a deleted row leaves no record to filter on."]}, {"id": "s4-04", "type": "single", "skill": "S4 · Monitoring and Alerting", "stem": "A pipeline has three expectations. After the latest update, the data lead wants the number of rows that failed each expectation, per dataset. The pipeline ran successfully and nothing was written to any error table. Where are these counts recorded?", "options": ["In the job run output of the job that triggered the pipeline update, per task", "In the flow progress events of the pipeline event log, in the data quality section", "In the billing usage table, in the usage metadata for the pipeline, per day", "In the driver log of the compute that ran the pipeline update, in the last lines printed"], "answer": 1, "runner": 3, "runnerWhy": "the driver log records errors and prints, but it does not hold structured per-expectation counts, though it would win if the update had crashed.", "think": {"premise": "That a successful run leaves no record of data quality. Passed and failed row counts are written as structured events.", "map": [["Failed rows per expectation", "Event log, flow progress, data quality", "Parse the details JSON"], ["Pipeline crashed with an exception", "Driver log and the error event", "Read the stack trace"], ["Many pipelines in one query", "Pipeline events system table (Beta)", "Query across pipelines"]], "apply": [["\"per dataset\"", "Matches the dataset field inside each expectation record."], ["\"The pipeline ran successfully\"", "No crash, so logs have nothing to show."]], "rule": "Pipeline health and expectation counts live in the event log, not in cluster logs.", "guide": "Use Pipeline event logs to monitor pipeline health and data quality."}, "eli5": "The receipt for each parcel is stored with the parcel, not shouted across the shop.", "learn": "https://docs.databricks.com/aws/en/ldp/monitor-event-logs", "why": ["Works, but the job output reports task status and does not carry expectation counts.", "Best fit: flow progress events hold passed and failed record counts for each expectation and dataset.", "Works, but billing records usage units and says nothing about row quality.", "Works, but logs show errors and printed text, not structured counts, and the update did not crash."]}, {"id": "s5-06", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A team enables Change Data Feed on a large silver table today and expects the gold job to replay all changes since January. Tomorrow's first run reads from version zero and misses the earlier updates. What is the correct explanation?", "options": ["The feed only captures inserts, so updates are in the transaction log only", "The readChangeFeed option does not work with batch queries, only streams", "The feed was enabled but VACUUM removed the change files within the hour", "The feed records only changes made after it was enabled, so older history needs a snapshot"], "answer": 3, "runner": 2, "runnerWhy": "VACUUM can remove change files under retention, but it cannot be the cause here since the feed started today.", "think": {"premise": "That CDF is a history of the table. It starts recording when enabled.", "map": [["Changes before enabling", "Not recorded", "Backfill from a snapshot, then use the feed"], ["Old versions past retention", "Removed by VACUUM", "Archive changes to another table"], ["Batch reads", "Supported", "Use table_changes or readChangeFeed"]], "apply": [["\"enables ... today\"", "Anything before today was never recorded."], ["\"since January\"", "Needs a one-time backfill outside the feed."]], "rule": "The change feed has no past; backfill once, then follow it.", "guide": "Apply Change Data Feed (CDF) to expose row-level changes (updates/deletes) for efficient incremental downstream processing."}, "eli5": "A security camera only has footage from the day it was installed.", "learn": "https://docs.databricks.com/aws/en/delta/delta-change-data-feed", "why": ["Works, but the feed captures updates, deletes and inserts.", "Works, but batch reads are supported through table_changes and readChangeFeed.", "Works, but retention cleanup cannot remove changes that were never recorded, and the feed is a day old.", "Best fit: CDF records only changes after it was enabled."]}, {"id": "s8-03", "type": "single", "skill": "S8 · Debugging and Deploying", "stem": "A four-task job failed on its third task because a date parameter was wrong. The first two tasks succeeded and took two hours. The fix is only to supply the right date. How should the engineer recover?", "options": ["Repair the run and override the date parameter in the repair dialog", "Edit the job's default parameter and restart the whole run from the start", "Clone the job, remove the first two tasks, and run the copy", "Start a new run with Run now and enter the corrected date"], "answer": 0, "runner": 3, "runnerWhy": "Run now is a fine choice for a single-task job or when a fresh run is wanted, but here it repeats two hours of finished work.", "think": {"premise": "That a failed run must be redone in full. Repair keeps successful tasks and reruns only failed ones and their dependents.", "map": [["Later task failed, earlier succeeded", "Repair run", "Override the parameter and rerun"], ["Single-task job failed", "Run now", "Repair needs two or more tasks"], ["Continuous job in backoff", "Restart run", "Cancels and starts a new run"]], "apply": [["\"The first two tasks succeeded and took two hours\"", "Repair avoids redoing them."], ["\"only to supply the right date\"", "A parameter override in the repair dialog."]], "rule": "Repair reruns the failed task and its dependents with overridden parameters, and keeps what succeeded.", "guide": "Analyze the errors and remediate the failed job runs with job repairs and parameter overrides."}, "eli5": "Reheat only the burnt course, not the whole dinner.", "learn": "https://docs.databricks.com/aws/en/jobs/repair-job-failures", "why": ["Best fit: repair skips the two finished tasks and takes the new date as an override.", "Works, but a full restart also repeats the finished tasks and changes a default for later runs.", "Works, but a clone drops the original run's history and leaves a second job to maintain.", "Works, but a new run starts all tasks again and repeats the two hours of finished work."]}, {"id": "s8-04", "type": "single", "skill": "S8 · Debugging and Deploying", "stem": "A job with three tasks failed on task two because the notebook path in its settings was mistyped. The engineer corrected the path in the job. Task one had succeeded. What is the safest way to finish the run?", "options": ["Cancel the run, then recreate the job from its JSON definition with the fixed path", "Wait for the next scheduled run and let it pick up the corrected path overnight", "Start a fresh run with Run now so the corrected settings are used by every task", "Repair the run, since reruns use the current settings including the fixed path"], "answer": 3, "runner": 2, "runnerWhy": "Run now would win if the job had a single task, because repair needs at least two tasks.", "think": {"premise": "That a settings fix needs a fresh run. Repair applies the current job and task settings to the tasks it reruns.", "map": [["Settings fixed after a failure", "Repair uses current settings", "Repair the failed run"], ["Single-task job", "Run now", "Repair is not available"], ["Parameter was wrong", "Repair dialog override", "Enter the new value"]], "apply": [["\"corrected the path in the job\"", "Repair will use the corrected setting."], ["\"Task one had succeeded\"", "No need to redo it."]], "rule": "A repair picks up the job's current settings, so fix the job first and then repair.", "guide": "Analyze the errors and remediate the failed job runs with job repairs and parameter overrides."}, "eli5": "Mend the torn page and carry on from there.", "learn": "https://docs.databricks.com/aws/en/jobs/repair-job-failures", "why": ["Works, but recreating a job adds risk and loses the run's history for no gain.", "Works, but waiting delays the data for a day and leaves the failed run unresolved.", "Works, but it runs task one again and does not continue the same run.", "Best fit: only the failed task and its dependents rerun, now with the fixed path."]}, {"id": "s1-a02", "type": "single", "skill": "S1 · Developing Code", "stem": "A job on serverless compute stops at start-up after a teammate added a library to the environment. The pip log shows the library installs PySpark as a dependency. The job needs only the library's non-Spark functions, and its vendor publishes a core build with no PySpark dependency. What should you do first?", "options": ["Reset the environment to its defaults, then install the vendor's core build that has no PySpark dependency", "Pin every package in the environment to the version it had last month and rerun the job on serverless", "Add a pip flag to force the install to overwrite the PySpark version already present", "Move the job to a classic cluster and install the library there using a cluster init script"], "answer": 0, "runner": 3, "runnerWhy": "a classic cluster with an init script does run it, but it gives up serverless and wins only if no PySpark-free build of the library exists.", "think": {"premise": "That the fix for any install failure is to pin versions. Read the log first; the fault here is a dependency that serverless does not allow.", "map": [["Library pulls in PySpark on serverless", "Forbidden dependency", "Reset the environment, install a PySpark-free build"], ["Same version number but new file contents", "Stale cache", "Bump the package version so jobs pick it up"], ["Wheel has native code", "CPU architecture", "Include both x86_64 and aarch64 variants"], ["Library truly needs PySpark, no core build", "Serverless limit", "Use classic compute; the runner-up wins"]], "apply": [["\"installs PySpark as a dependency\"", "This is the documented cause, so version pinning is a guess."], ["\"publishes a core build with no PySpark dependency\"", "Makes a PySpark-free install possible, which rules out moving to classic compute."]], "rule": "Read the pip log for the real cause, then fix that cause; on serverless, do not install a library that installs PySpark.", "guide": "Apply troubleshooting techniques to dependency conflicts and installation failures for external libraries (PyPI, local wheels, source archives) across serverless, pipeline, and bundle-deployed environments."}, "eli5": "If a guest brings an extra oven that blows the fuses, you swap it for a model that does not; you do not rewire every plug.", "learn": "https://docs.databricks.com/aws/en/compute/serverless/dependencies", "why": ["Best fit: the docs say to reset the environment after such a library stops the session, and a core build avoids the dependency.", "Works, but pinning old versions does not remove the PySpark dependency that stops the session.", "Works, but forcing an overwrite of PySpark is what breaks the session and is not a supported fix.", "Works, but it abandons serverless and adds init script upkeep when a PySpark-free build exists."]}, {"id": "s8-05", "type": "single", "skill": "S8 · Debugging and Deploying", "stem": "A team defines a job and a pipeline by hand in development and now needs the same set deployed to staging and production from CI on every merge. Reviewers want the definitions in pull requests. Which approach fits?", "options": ["Exported job JSON that an engineer imports into each workspace after each merge", "A Git folder in each workspace that is pulled to the main branch on merge", "A Declarative Automation Bundle with a target per environment, deployed by the CLI in CI", "A notebook that calls the Jobs API to create the job when someone runs it"], "answer": 2, "runner": 1, "runnerWhy": "a Git folder is a recommended way to sync notebooks and would win if only code files had to follow a branch with no jobs or pipelines.", "think": {"premise": "That syncing code also deploys the jobs that run it. A Git folder updates files, while a bundle describes and deploys resources.", "map": [["Jobs and pipelines to several environments", "Bundle with targets", "Validate and deploy in CI"], ["Only notebooks follow a branch", "Production Git folder", "Update by automation"], ["One-off experiment", "UI", "Create by hand"]], "apply": [["\"the same set deployed to staging and production\"", "Targets per environment."], ["\"definitions in pull requests\"", "Resources as YAML in the repository."]], "rule": "Resources as code deployed by the CLI mean a bundle, with one target per environment.", "guide": "Deploy Databricks resources using Declarative Automation Bundles (formerly Databricks Asset Bundles)."}, "eli5": "Ship the blueprint, not a photo of the building.", "learn": "https://docs.databricks.com/aws/en/dev-tools/bundles/", "why": ["Works, but manual import is unreviewed and drifts between environments over time.", "Works, but a Git folder syncs files and does not create or update jobs and pipelines.", "Best fit: the bundle keeps jobs and pipelines as reviewed YAML and deploys per target.", "Works, but a notebook run by hand is not tied to merges and is hard to review."]}, {"id": "s1-b07", "type": "single", "skill": "S1 · Developing Code", "stem": "A windowed count of clicks per five-minute window feeds a billing table. Each window must be written once, with its final value, and the team accepts a delay of about ten minutes. Which output setup fits?", "options": ["Update output mode with a ten-minute watermark on the event time column", "Append output mode with a ten-minute watermark on the event time column", "Complete output mode with no watermark on the event time column", "Append output mode with no watermark, relying on the checkpoint to finalize windows"], "answer": 1, "runner": 0, "runnerWhy": "update mode emits early results that later change, and it wins when readers want early numbers and can accept corrections.", "think": {"premise": "That the checkpoint decides when a window is final. The watermark does; append mode writes a window only after the watermark passes it.", "map": [["Each window once, final value", "Output mode", "Append with a watermark"], ["Early, correctable results", "Output mode", "Update"], ["Whole result rewritten each trigger", "Complete mode", "Keeps all state; only for small results"]], "apply": [["\"written once, with its final value\"", "Append mode, which emits a window only after the watermark passes."], ["\"accepts a delay of about ten minutes\"", "A ten-minute watermark matches the delay."]], "rule": "Final once: append with a watermark; early and revised: update; whole table each time: complete.", "guide": "Apply Structured Streaming stateful-processing semantics, including watermarks, output modes, foreachBatch, and checkpoints for fault-tolerant exactly-once state recovery."}, "eli5": "A teacher who reads out each class's final score only after the late work deadline.", "learn": "https://docs.databricks.com/aws/en/structured-streaming/watermarks", "why": ["Works, but update writes windows as they change, so the billing table sees revised values.", "Best fit: append writes each window once after the watermark passes, with the ten-minute delay.", "Works, but complete mode keeps all state and rewrites the entire target on every trigger.", "Works, but without a watermark an aggregation cannot finalize windows in append mode, and the checkpoint does not help."]}, {"id": "s2-07", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "Analysts must query a PostgreSQL reporting database from Databricks. The database owner will not let the analysts see the password, and every access must go through Unity Catalog permissions. The analysts only read data. What should the platform team create?", "options": ["A Lakeflow Connect pipeline that copies the tables into managed Delta tables nightly", "A shared cluster whose init script stores the password in an environment variable", "A Unity Catalog connection holding the credentials, a foreign catalog on it, and grants on the tables", "A secret scope with the password, referenced by each analyst's notebook JDBC code"], "answer": 2, "runner": 0, "runnerWhy": "copying into Delta is sound for heavy repeated queries and would win if load on the source mattered; it adds a pipeline and staleness for plain read access.", "think": {"premise": "That credentials must travel with the user. In federation the connection stores them and users only get privileges on foreign tables.", "map": [["Password must stay hidden", "Where credentials live", "On the Unity Catalog connection"], ["Queries must follow UC permissions", "Governance", "Foreign catalog with grants"], ["Heavy repeated queries hurting the source", "Where the runner-up wins", "Ingest a copy"]], "apply": [["\"will not let the analysts see the password\"", "Rules out passwords in notebooks or init scripts."], ["\"every access must go through Unity Catalog permissions\"", "Points to a foreign catalog."]], "rule": "Federation keeps the credential on the connection and exposes tables through Unity Catalog grants.", "guide": "Configure Lakehouse Federation with governance across supported source systems, applying UC permissions and connection-level credentials."}, "eli5": "The front desk holds the key and lets approved visitors into the room without ever handing it over.", "learn": "https://docs.databricks.com/aws/en/query-federation/", "why": ["Works, but it adds a copy and a nightly delay for analysts who only need read access.", "Works, but the password then sits on the cluster, outside Unity Catalog governance.", "Best fit: the connection stores the credentials and the foreign catalog applies Unity Catalog grants to reads.", "Works, but each notebook still needs the secret and bypasses Unity Catalog permissions and audit."]}, {"id": "s1-b06", "type": "single", "skill": "S1 · Developing Code", "stem": "A streaming query uses foreachBatch to append each micro-batch to a Delta table. After an executor failure the query restarts and replays the last batch, and the table now holds duplicate rows. The checkpoint is intact. What is the best fix?", "options": ["Delete the checkpoint directory and restart so that the query begins from a clean state", "Set txnAppId and txnVersion to the batchId in the Delta write inside foreachBatch", "Switch the query to complete output mode so that the target is rewritten each trigger", "Add dropDuplicatesWithinWatermark on the event id column before the Delta write"], "answer": 1, "runner": 3, "runnerWhy": "deduplication on an event id inside a watermark works when each event has a unique id, but replays outside the watermark are not guaranteed to be caught.", "think": {"premise": "That an intact checkpoint makes a foreachBatch write exactly once. foreachBatch alone gives at-least-once writes, so a replayed batch writes again.", "map": [["Replayed batch writes twice", "Sink idempotency", "txnAppId plus txnVersion equal to batchId"], ["Events carry unique ids", "Deduplication", "dropDuplicatesWithinWatermark"], ["New checkpoint started", "Batch ids restart at 0", "Change txnAppId too"]], "apply": [["\"replays the last batch\"", "A replay writes again unless the write is idempotent."], ["\"The checkpoint is intact\"", "Rules out deleting it, which would reprocess everything."]], "rule": "A checkpoint remembers progress; an idempotent write makes replays harmless.", "guide": "Apply Structured Streaming stateful-processing semantics, including watermarks, output modes, foreachBatch, and checkpoints for fault-tolerant exactly-once state recovery."}, "eli5": "Stamp each delivery with a ticket number, so a driver bringing the same parcel twice is turned away.", "learn": "https://docs.databricks.com/aws/en/structured-streaming/foreach", "why": ["Works, but a clean start reprocesses the source from the beginning and creates far more duplicates.", "Best fit: Delta skips a write with a batch id it has already seen, so a replay adds nothing.", "Works, but complete mode rewrites the whole result each trigger and does not address a replayed append.", "Works, but it only catches duplicates that fall within the watermark and needs a unique event id."]}, {"id": "s7-01", "type": "single", "skill": "S7 · Data Governance", "stem": "Analysts at a manufacturer want to find every supplier table across many schemas by filtering on one exact business-area label in workspace search. The team must not move data or change who can read it. Which action fits?", "options": ["Rename the tables with a supplier_ prefix and keep them in the schemas where they already sit", "Write a clear comment on each supplier table and column that describes the supplier data it holds", "Set a TBLPROPERTIES entry such as domain = supplier on each supplier table in the Delta metadata", "Apply a tag with key domain and value supplier to each supplier table, then search on that key and value"], "answer": 3, "runner": 1, "runnerWhy": "comments win when the gap is understanding what a table or column means rather than grouping tables by an exact label.", "think": {"premise": "That any metadata field supports label search. Tags are key and value pairs that workspace search can filter on; comments are free text that explains.", "map": [["Need to group tables by business area", "Tags", "Add key and value tags"], ["Need to explain what a column means", "Comments", "COMMENT on tables and columns; the runner-up wins"], ["Label must be searchable in the catalog", "Unity Catalog tags, not Delta properties", "Use tags"]], "apply": [["\"one exact business-area label\"", "Points to a key and value tag, not free text."], ["\"must not move data or change who can read it\"", "Rules out renames that break queries and any access grants."]], "rule": "Tags label and group, comments explain, and search filters on the tag's key and value.", "guide": "Demonstrate understanding of Unity Catalog tags and comments as mechanisms for adding metadata to securable objects to improve data discoverability."}, "eli5": "Like labels on boxes in a store room: you find the right box without opening each one.", "learn": "https://docs.databricks.com/aws/en/database-objects/tags", "why": ["Works, but renaming breaks existing queries that use the old names and gives no key and value to filter on.", "Works, but a comment is free text that explains meaning and does not give one exact label to filter on.", "Works, but a Delta table property is a table setting, not the Unity Catalog tag feature that search filters on.", "Best fit: a tag is a key and value on the object, searchable by exact term, and changes nothing about data or access."]}, {"id": "s4-01", "type": "single", "skill": "S4 · Monitoring and Alerting", "stem": "A finance lead wants last month's compute spend grouped by job across all workspaces in the account, with the dollar amount, not only the usage units. Nobody wants to open jobs one at a time. Which approach answers this directly?", "options": ["Call the Jobs API for every job's runs and sum the cluster sizes from each run", "Open each job in the Jobs UI and add up the run durations for the month", "Query the audit system table for job run events and multiply by a flat hourly rate", "Join the billing usage system table to the list prices table and group by the job ID"], "answer": 3, "runner": 1, "runnerWhy": "it works for one job's history, but it gives durations rather than dollars and cannot span workspaces without manual effort.", "think": {"premise": "That cost is visible in the Jobs UI. The UI shows durations, while dollars come from billed usage multiplied by price.", "map": [["Cost across workspaces and weeks", "Billing system tables", "Join usage to list prices"], ["One live run slow today", "Jobs UI timeline", "Open the run and compare task times"], ["Who changed a permission", "Access audit table", "Query the audit log"]], "apply": [["\"across all workspaces in the account\"", "Rules out per-job screens."], ["\"the dollar amount, not only the usage units\"", "Points to list prices joined to usage."]], "rule": "Account-wide cost is a join of billed usage and list prices, grouped by the job ID recorded in usage metadata.", "guide": "Use Databricks system tables (billing, compute, access, lakeflow) for cost analysis, auditing, and workload monitoring."}, "eli5": "Read the shop's till receipts instead of asking each customer how long they stayed.", "learn": "https://docs.databricks.com/aws/en/admin/system-tables/", "why": ["Works, but cluster sizes in runs do not give billed units or prices and need one call per job.", "Works, but durations are not dollars and the work is manual for every job and workspace.", "Works, but audit events record actions, not billed usage, and a flat rate hides real price differences.", "Best fit: usage records carry the job ID and the price table turns units into money for the whole account."]}, {"id": "s4-06", "type": "single", "skill": "S4 · Monitoring and Alerting", "stem": "Last night's four-task job finished two hours later than usual. The engineer wants to see which task took the extra time in that one run, and open its logs. No trend over months is needed. Where should the engineer start?", "options": ["The run page in the Jobs UI, using the timeline view and then the slow task's logs", "The billing usage table, grouped by the job's compute type for last night", "The job task run timeline system table, comparing durations across the past year", "The audit system table, filtered to events from the job's service principal"], "answer": 0, "runner": 2, "runnerWhy": "system tables win when the question becomes a trend over months, because UI run history is kept for 60 days.", "think": {"premise": "That the system tables are the first stop for every job question. One fresh run with logs is faster to read in the Jobs UI.", "map": [["One recent run, which task was slow", "Jobs UI timeline", "Open the task for logs and metrics"], ["Compare against months of runs", "Lakeflow system tables", "Query task run timeline"], ["Cost of the run", "Billing usage", "Join to list prices"]], "apply": [["\"in that one run\"", "Single run scope."], ["\"open its logs\"", "Logs are reached from the run page."]], "rule": "For one recent run use the Jobs UI; for trends and long history use system tables.", "guide": "Use Lakeflow Jobs UI and Jobs API to monitor job status and performance metrics."}, "eli5": "Look at last night's receipt rather than the year's accounts.", "learn": "https://docs.databricks.com/aws/en/jobs/monitor", "why": ["Best fit: the timeline view shows task overlap and duration for that run and links straight to logs.", "Works, but it explains cost and not why one task ran long.", "Works, but it gives timing rows and not logs, and a year of history is more than the question needs.", "Works, but audit events record actions and do not show task timing."]}, {"id": "s3-03", "type": "single", "skill": "S3 · Data Manipulation", "stem": "An app team sends event records as JSON where each app adds different fields and new fields appear monthly. Analysts mostly read a few fields per query. The team wants to store the records without redesigning a schema each month and to read fields with real types. What should you use?", "options": ["A STRING column holding the raw JSON text, read with get_json_object on every query", "A VARIANT column filled with parse_json, read with variant_get or the colon path and a cast", "A MAP of string to string, with every value cast on read in the consuming queries", "A STRUCT column with every field seen so far, altered with ALTER TABLE whenever a new field appears"], "answer": 1, "runner": 3, "runnerWhy": "a struct gives real types and statistics up front and wins when the shape is stable; here the monthly drift forces constant schema changes.", "think": {"premise": "That flexible shape means storing text. VARIANT keeps irregular records in a binary form that is cheaper to read and still flexible.", "map": [["Shape changes often", "Column type", "VARIANT via parse_json"], ["Need a typed field", "Extraction", "variant_get with a type, or colon path with a cast"], ["Shape is fixed and known", "Where the runner-up wins", "STRUCT"]], "apply": [["\"each app adds different fields\"", "Rules out a fixed struct."], ["\"read fields with real types\"", "Rules out a string-only map and favours a cast on a variant."]], "rule": "Changing shape plus typed reads means VARIANT.", "guide": "Develop a model and query semi-structured data using the VARIANT data type and related functions (e.g., parse_json, variant_get)."}, "eli5": "A filing cabinet with expandable folders instead of a printed form for every new kind of letter.", "learn": "https://docs.databricks.com/aws/en/semi-structured/variant", "why": ["Works, but the text is parsed again on every query and carries no type help.", "Best fit: VARIANT stores any shape without schema changes and lets you extract typed fields by path.", "Works, but everything is a string, so nested values and numbers need casts and lose structure.", "Works, but each new field means an ALTER and null columns for records that do not have it."]}, {"id": "s5-01", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A retailer has sixty Delta tables in Unity Catalog. An engineer spends each week adjusting OPTIMIZE and VACUUM jobs, and the team wants that work to disappear without writing new automation. All tables are written only by Databricks pipelines. What should they do?", "options": ["Turn on auto compaction and optimized writes on each table and drop the scheduled jobs", "Move the tables to external storage and run one shared maintenance job from Lakeflow Jobs", "Keep the tables as Unity Catalog managed tables and enable Predictive Optimization", "Add a nightly notebook that runs OPTIMIZE and VACUUM on every table in a loop"], "answer": 2, "runner": 1, "runnerWhy": "a shared scheduled job works and is simple, but a person still owns it; it wins if the tables must stay external because another system writes the files, since Predictive Optimization skips external tables.", "think": {"premise": "That maintenance is always a job someone must schedule. For managed tables Databricks runs it for you.", "map": [["Many tables, weekly manual tuning", "Operational overhead", "Predictive Optimization on managed tables"], ["Files owned by another system", "Table type", "External tables, so you schedule jobs yourself"], ["Compaction only, no VACUUM or statistics", "Partial coverage", "Write-time settings do not replace full maintenance"]], "apply": [["\"without writing new automation\"", "Rules out the scheduled loops and shared jobs."], ["\"written only by Databricks pipelines\"", "Nothing forces external storage, so managed tables are allowed."]], "rule": "Managed tables plus Predictive Optimization turn maintenance from a job you own into a service you switch on.", "guide": "Explain how Unity Catalog managed tables, Predictive Optimization, and Liquid Clustering reduce operational and maintenance overhead for a given workload."}, "eli5": "A self-cleaning oven instead of a weekly scrubbing rota.", "learn": "https://docs.databricks.com/aws/en/optimizations/predictive-optimization", "why": ["Works, but write-time settings do not run VACUUM or collect statistics, so maintenance is only partly covered.", "Works, but external tables are skipped by Predictive Optimization and the job still needs an owner.", "Best fit: Predictive Optimization runs OPTIMIZE, VACUUM and ANALYZE on managed tables automatically.", "Works, but it is still hand-built automation that someone must monitor, tune and fix when it fails."]}, {"id": "s3-02", "type": "single", "skill": "S3 · Data Manipulation", "stem": "A pipeline joins a clickstream table to a customers table on email address to count clicks per customer. After the join, total clicks are almost double the clickstream row count. The customers table is a daily load and nothing else changed. What should you check first?", "options": ["Whether email is unique in the customers table, since duplicate keys multiply matching rows", "Whether the count should use approx_count_distinct to avoid double counting in Spark", "Whether the join is a left join instead of an inner join, which would add extra rows for unmatched clicks", "Whether the clickstream table needs more shuffle partitions set before it is joined to customers"], "answer": 0, "runner": 2, "runnerWhy": "join type does change which rows appear, but a left join only keeps unmatched rows once; it does not double matched ones, so it would win only if rows were missing.", "think": {"premise": "That inflated counts mean a Spark bug. A join on a non-unique key multiplies rows, which is a data fact to check first.", "map": [["Row count grows after a join", "Key uniqueness", "Check duplicates in the lookup side"], ["Rows missing after a join", "Where the runner-up wins", "Check inner versus left join"], ["Join is slow but correct", "Partitions or broadcast", "Tune the shuffle"]], "apply": [["\"almost double the clickstream row count\"", "Points to duplicate keys on the other side, not to dropped rows."], ["\"The customers table is a daily load\"", "A reload can append duplicates."]], "rule": "More rows after a join means a duplicate key on one side.", "guide": "Apply advanced data transformations, including window functions, joins, and aggregations, using Spark SQL and PySpark to process large datasets."}, "eli5": "If two people share one name on a guest list, each ticket gets handed out twice.", "learn": "https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-join", "why": ["Best fit: duplicate emails on the lookup side fan out each click to several rows, matching the symptom.", "Works, but an approximate count would hide the duplicates, not fix the join.", "Works, but a left join keeps unmatched rows once and cannot double matched rows.", "Works, but partitions change speed and not the number of rows the join produces."]}, {"id": "s8-02", "type": "single", "skill": "S8 · Debugging and Deploying", "stem": "A nightly notebook job on a cluster takes four hours, and one stage keeps ten tasks running for a long time while the other two hundred finish in a minute. The engineer wants evidence of which tasks are slow. Where should the engineer look?", "options": ["The stage page in the Spark UI, comparing task durations and data sizes", "The billing usage system table, grouped by the job's compute", "The query profile of a SQL warehouse, filtered to the last night", "The audit system table, filtered to the job's run-as user"], "answer": 0, "runner": 2, "runnerWhy": "the query profile is the right tool and would win if the slow work were a SQL warehouse query, but this job runs on a cluster.", "think": {"premise": "That a long job needs a history query. Uneven tasks inside one stage are visible in the Spark UI.", "map": [["A few tasks far slower than peers", "Spark UI stage page", "Compare durations and sizes"], ["SQL warehouse query slow", "Query profile", "Open top operators"], ["Has this happened before", "Lakeflow system tables", "Query run history"]], "apply": [["\"ten tasks running ... while the other two hundred finish in a minute\"", "Task-level imbalance inside a stage."], ["\"on a cluster\"", "Spark UI applies, not a warehouse profile."]], "rule": "Imbalance between tasks of one stage is read on that stage's page in the Spark UI.", "guide": "Identify pertinent diagnostic information using Spark UI, cluster logs, system tables, and query profiles to troubleshoot errors."}, "eli5": "Compare the runners in one race, not the season table.", "learn": "https://docs.databricks.com/aws/en/compute/troubleshooting/debugging-spark-ui", "why": ["Best fit: the stage page lists every task's duration and size, so the slow few stand out.", "Works, but billing rows show cost and not which tasks within a stage were slow.", "Works, but the job ran on a cluster, so no warehouse profile exists for it.", "Works, but audit events record actions and carry no task timing."]}, {"id": "s6-02", "type": "single", "skill": "S6 · Security and Compliance", "stem": "A retailer has about 400 tables across many schemas, and customer email columns appear in dozens of them under different names. New tables arrive weekly. Support staff must see a masked email, while the privacy team sees the real value. How should you enforce this?", "options": ["Tag email columns with a governed tag and add one ABAC mask policy on the catalog for support, exempting the privacy team", "Create a dynamic view over each table that checks is_account_group_member and returns a masked email to support staff", "Write one masking function and run ALTER TABLE ... ALTER COLUMN email SET MASK on each email column in every existing table", "Keep an unmasked copy of each table for the privacy team and a masked copy for support staff, rebuilt nightly"], "answer": 0, "runner": 2, "runnerWhy": "per-column masks are fully supported and would win when only a few tables hold email and no governed tags exist.", "think": {"premise": "That a mask must be attached table by table. A policy keyed on a governed tag follows the tag, so new tagged columns are covered without further work.", "map": [["Same sensitive type in many tables", "ABAC policy with governed tags", "One policy at catalog or schema level"], ["New tables arrive weekly", "Policy applies when the tag appears", "Tag the new column; no new mask needed"], ["Only two tables, no tags", "Per-column SET MASK", "Simple and sufficient"]], "apply": [["\"about 400 tables\"", "Makes per-table work costly and error-prone."], ["\"New tables arrive weekly\"", "Per-table masks would have to be repeated each time."], ["\"different names\"", "Matching by name fails, matching by tag works."]], "rule": "Many tables and many new ones point to tag-driven policy; few tables point to per-column masks.", "guide": "Apply attribute-based access control (ABAC) policies with governed tags to enforce row filters and column masks at scale."}, "eli5": "Instead of taping a cover over every window, you give the rule to the building: any window with a blue sticker gets frosted glass.", "learn": "https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/", "why": ["Best fit: one tag-driven policy covers all current and future email columns and exempts the privacy team.", "Works, but views need one definition each, must block direct table access, and also do not follow new tables automatically.", "Works, but it is repeated for every table and must be redone for each new table.", "Works, but duplicated copies double storage, drift apart, and add a sync job to maintain."]}, {"id": "s6-01", "type": "single", "skill": "S6 · Security and Compliance", "stem": "A group of auditors must run SELECT queries on one table, sales.reports.invoices, and must not see any other table in the catalog or be able to change anything. Other tables in the same schema hold payroll data. Which set of grants applies least privilege?", "options": ["USE CATALOG on sales and SELECT on the sales.reports schema, granted to the auditors group, with no table grants", "SELECT on the sales catalog, granted to the auditors group, with a row filter on each payroll table", "USE CATALOG on sales, USE SCHEMA on sales.reports and SELECT on the invoices table, for the auditors group", "USE CATALOG on sales, USE SCHEMA on sales.reports, and ALL PRIVILEGES on the invoices table, granted to the group"], "answer": 2, "runner": 0, "runnerWhy": "schema-level SELECT is a fine, common pattern and would win if the schema held only tables the auditors may read, because it also covers future tables.", "think": {"premise": "That one SELECT grant is all a reader needs, or that wider is simply easier. Usage privileges open the door and SELECT opens the table, and each should sit at the lowest level that fits.", "map": [["Reader of a single table", "Table-level SELECT plus the two usage privileges", "Grant to a group at the table"], ["Reader of every table in a schema", "Schema-level SELECT", "Grant once; covers future tables, so it wins when all are allowed"], ["Schema mixes allowed and forbidden tables", "Table-level grants", "Avoid inheritance from the schema"]], "apply": [["\"one table\"", "Rules out schema and catalog level SELECT, which are inherited by every child."], ["\"Other tables in the same schema hold payroll data\"", "Rules out the schema-level grant."], ["\"must not ... be able to change anything\"", "Rules out ALL PRIVILEGES."]], "rule": "Grant at the lowest level that covers the need, and remember the two usage privileges on the parents.", "guide": "Apply least-privilege access control lists (ACLs) to secure Unity Catalog securable objects and workspace resources."}, "eli5": "Give the visitor a key to one room, plus permission to walk through the front door and the corridor, not the master key to the building.", "learn": "https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges", "why": ["Works, but SELECT on the schema is inherited by every table there, including payroll.", "Works, but a catalog-level SELECT reaches every table and relies on filters on each payroll table to claw access back.", "Best fit: it gives the two usage privileges and read access on exactly one table, and nothing inherited from above.", "Works, but ALL PRIVILEGES allows changes to the table, which the stem forbids."]}, {"id": "s5-04", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A cluster with local SSD workers runs the same reporting queries over one large Delta table all afternoon. Cloud storage reads dominate, the data changes only overnight, and the team wants a faster result without code changes. What helps most?", "options": ["Increase the cluster's driver memory so more results are held in memory", "Convert the table to a materialized view that is refreshed each morning", "Rely on the disk cache that keeps copies of read files on worker SSDs", "Call df.cache() on the table's DataFrame at the top of every report"], "answer": 2, "runner": 3, "runnerWhy": "the Spark cache works but needs code changes and uses memory; it wins when one job reuses an expensive computed DataFrame several times.", "think": {"premise": "That caching means writing cache calls. The disk cache works on its own for Parquet and Delta reads.", "map": [["Same files read repeatedly", "I/O from cloud storage", "Disk cache"], ["Computed DataFrame reused in a job", "Compute", "Spark cache"], ["Same aggregate for many users", "Pre-computation", "Materialized view"]], "apply": [["\"without code changes\"", "Rules out df.cache() calls."], ["\"Cloud storage reads dominate\"", "Local file copies attack exactly that cost."]], "rule": "Repeated reads of the same files point to the disk cache.", "guide": "Understand how caching (Delta cache) improves query performance for repeated reads of the same data."}, "eli5": "Keeping the books you reread on your desk instead of walking to the library.", "learn": "https://docs.databricks.com/aws/en/optimizations/disk-cache", "why": ["Works, but driver memory does not store file data from workers.", "Works, but it changes the architecture and only helps if the reports share one aggregate.", "Best fit: the disk cache fills on first read and serves repeated reads locally with no code changes.", "Works, but it needs edits in every report and holds blocks in memory."]}, {"id": "s2-04", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "A telecom's change feed lands in Lakeflow Pipelines with a key and a sequence column, and some events share the same timestamp. Two updates to one customer carry identical timestamps but different record ids. The latest one must win, and the pipeline fails if the sequence value is null. How do you order the changes?", "options": ["Sequence by the timestamp alone and let the pipeline choose between tied rows", "Sequence by the file arrival time, which is never null and always increases", "Sequence by a STRUCT of the timestamp and the record id, which breaks the tie", "Add a deduplication step that drops one of the tied events before applying changes"], "answer": 2, "runner": 3, "runnerWhy": "dropping events before applying changes can work, but it discards one of two real updates and you must choose the survivor yourself.", "think": {"premise": "That one timestamp column is enough to order changes. When values can tie, combine columns in a STRUCT so the order is total.", "map": [["Ties on the sequence column", "Ordering key", "STRUCT(timestamp, id)"], ["Null sequence values", "Input quality", "Not supported; filter or fix first"], ["Tied rows are true duplicates", "Where the runner-up wins", "Deduplicate before applying"]], "apply": [["\"identical timestamps but different record ids\"", "Two distinct updates, so a tie-break is needed rather than dropping one."], ["\"The latest one must win\"", "Needs a deterministic order."]], "rule": "When the sequence can tie, sequence by a STRUCT of columns.", "guide": "Configure incremental CDC pipelines using Lakeflow Pipelines with Delta or Iceberg as the target table format."}, "eli5": "If two letters carry the same postmark, look at the ticket number stapled to each.", "learn": "https://docs.databricks.com/aws/en/ldp/cdc", "why": ["Works, but tied events then have no defined order and the winner can vary between runs.", "Works, but arrival time reflects when files landed, not when changes happened, so out-of-order events overwrite newer ones.", "Best fit: a STRUCT of timestamp then record id gives a strict order, so the later record always wins.", "Works, but you discard one real update and must invent a rule for which one survives."]}, {"id": "s3-07", "type": "single", "skill": "S3 · Data Manipulation", "stem": "A regulator-facing pipeline computes a daily total from a payments feed. If any row has a negative amount, the published total would be wrong and must not be released. Rows are never corrected downstream. How should you configure the expectation on the amount?", "options": ["Use the default warn action, and monitor the data quality metrics after each run", "Use drop, so negative rows are removed and the total is computed from the remaining rows", "Use fail update, so the update stops and rolls back the table instead of publishing a wrong total", "Write negative rows to a quarantine table and continue with the remaining rows"], "answer": 2, "runner": 1, "runnerWhy": "dropping and carrying on is right when a partial total is acceptable; here a total missing rows would be silently wrong.", "think": {"premise": "That dropping bad data is always the safest. When any bad row makes the output wrong, failing is the safe action.", "map": [["One bad row invalidates the output", "Action", "Fail update, atomic rollback"], ["Partial result is acceptable", "Where the runner-up wins", "Drop"], ["Bad rows need review", "Pattern", "Quarantine table"]], "apply": [["\"must not be released\"", "A hard stop is needed."], ["\"Rows are never corrected downstream\"", "Nothing repairs a partial result later."]], "rule": "If one bad row makes the answer wrong, fail the update.", "guide": "Implement data quality expectations in Lakeflow Pipelines to quarantine, drop, or fail on bad records."}, "eli5": "A scale that refuses to print a receipt if one item is mislabeled, rather than printing a quietly wrong total.", "learn": "https://docs.databricks.com/aws/en/ldp/expectations", "why": ["Works, but warn keeps negative rows in the data and publishes the wrong total anyway.", "Works, but the total silently omits rows and looks valid.", "Best fit: fail update stops and rolls back that table update, so no wrong total is published.", "Works, but it still publishes a total computed without those rows, which is wrong for the regulator."]}, {"id": "s3-05", "type": "single", "skill": "S3 · Data Manipulation", "stem": "A support platform holds two million existing ticket rows in a Delta table. A scheduled Lakeflow Pipelines step must add a sentiment label to each row using a model on a Model Serving endpoint. A few rows may fail, and a failed row must not stop the run. Which design fits?", "options": ["A new notebook that an analyst runs by hand to label tickets in small batches", "ai_query over the table in the pipeline step, with failOnError set to false", "The built-in ai_analyze_sentiment function applied to the ticket text column", "A pandas UDF that posts each batch of rows to the endpoint's REST API"], "answer": 1, "runner": 2, "runnerWhy": "ai_analyze_sentiment is a ready-made task function and is the better choice when any sentiment model will do; it loses here because the stem requires the team's own model on a serving endpoint.", "think": {"premise": "That inference needs application code. ai_query lets SQL send each row to an endpoint and return the answer as a column.", "map": [["Label every row of a table", "Tool", "ai_query in the pipeline step"], ["A few rows may fail", "Error handling", "failOnError false returns a struct with the error"], ["Any sentiment model is acceptable", "Where the runner-up wins", "Use the built-in ai_analyze_sentiment task function"]], "apply": [["\"two million existing ticket rows\"", "Needs set-based inference, not row-by-row calls from code."], ["\"using a model on a Model Serving endpoint\"", "Rules out the built-in task function, which does not use the team's endpoint."], ["\"a failed row must not stop the run\"", "failOnError set to false."]], "rule": "Row-level model calls inside a pipeline are ai_query; set failOnError false to tolerate bad rows.", "guide": "Apply AI functions, including ai_query, to perform model inference within data pipelines for enrichment and classification tasks."}, "eli5": "Hand the whole stack of tickets to the reader and let them mark each one, rather than walking to the expert for every page.", "learn": "https://docs.databricks.com/aws/en/sql/language-manual/functions/ai_query", "why": ["Works, but it is manual and not part of the scheduled pipeline the stem asks for.", "Best fit: ai_query runs across the table in parallel, and failOnError false returns an error value instead of stopping.", "Works, but it uses a general-purpose model chosen by Databricks, not the team's own endpoint the stem requires.", "Works, but you must build batching, retries and per-row error handling yourself, which failOnError already provides."]}, {"id": "s5-02", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A managed events table is filtered by customer one quarter, by device type the next, and by region after that. Analysts never announce the change, and the team does not want to revisit the table design each time. Which setting fits this access pattern?", "options": ["Partitioning by event date so every filter reads fewer folders", "CLUSTER BY AUTO so Predictive Optimization picks and updates the keys", "ZORDER BY customer, device type and region on every OPTIMIZE run", "CLUSTER BY on customer, with a plan to run ALTER TABLE when filters change"], "answer": 1, "runner": 3, "runnerWhy": "explicit keys work well and give control; they win if the filter columns were known and stable.", "think": {"premise": "That a person must pick clustering keys. With automatic clustering the platform learns them from query history.", "map": [["Filter columns drift without notice", "Access pattern", "CLUSTER BY AUTO"], ["Columns known and stable", "Access pattern", "Explicit CLUSTER BY"], ["Few low-cardinality filters tied to dates", "Layout", "Partitioning"]], "apply": [["\"never announce the change\"", "Nobody will tell you when to change keys, ruling out manual re-keying."], ["\"does not want to revisit the table design\"", "Points to automatic key selection."]], "rule": "Unpredictable filters mean let the platform choose the keys.", "guide": "Choose the appropriate Delta optimization technique (deletion vectors, Liquid Clustering, CLUSTER BY AUTO) for a given table access pattern."}, "eli5": "A shop assistant who rearranges shelves by what people actually ask for.", "learn": "https://docs.databricks.com/aws/en/delta/clustering", "why": ["Works, but date folders do not help filters on customer, device or region.", "Best fit: CLUSTER BY AUTO chooses keys from usage and changes them when savings outweigh cost.", "Works, but ZORDER cannot be combined with clustering and needs manual columns and repeated rewrites.", "Works, but a person must notice the new pattern and change the keys, which the team wants to avoid."]}, {"id": "s1-b01", "type": "single", "skill": "S1 · Developing Code", "stem": "A bank receives a change feed for customer records with a key, an operation column and a sequence number. Auditors must be able to see the address a customer had on any past date. The pipeline is written in Python in Lakeflow Pipelines. How should the target table be built?", "options": ["Write a foreachBatch function that runs a MERGE ordered by arrival time", "Call create_auto_cdc_flow with keys, sequence_by and stored_as_scd_type set to 1", "Call create_auto_cdc_flow with keys, sequence_by and stored_as_scd_type set to 2", "Overwrite the target nightly from a snapshot of the source table"], "answer": 2, "runner": 1, "runnerWhy": "type 1 is simpler and smaller, and it wins when only the current row per key is needed; here auditors need past addresses, which type 1 overwrites.", "think": {"premise": "That every CDC target should hold only the latest row. Type 2 keeps each version, with __START_AT and __END_AT showing when it was active.", "map": [["History needed for past dates", "SCD type", "stored_as_scd_type 2"], ["Only the current state needed", "SCD type", "stored_as_scd_type 1"], ["Changes can arrive out of order", "Ordering", "sequence_by, not arrival time"]], "apply": [["\"address a customer had on any past date\"", "Needs history, so type 2; rules out type 1 and the overwrite."], ["\"a sequence number\"", "Gives sequence_by a proper ordering column, so hand-built arrival-time logic is unnecessary."]], "rule": "If someone will ask what it was before, store it as type 2; if they only ask what it is now, type 1.", "guide": "Implement CDC pipelines using AUTO CDC APIs (formerly APPLY CHANGES) in Lakeflow Pipelines, including SCD Type 1 and Type 2 via stored_as_scd_type."}, "eli5": "A type 1 notebook erases the old page; a type 2 notebook adds a new page and keeps the old one.", "learn": "https://docs.databricks.com/aws/en/dlt/cdc", "why": ["Works, but ordering by arrival time puts late changes in the wrong place, and you maintain the merge yourself.", "Works, but type 1 overwrites the old address, so the audit question cannot be answered.", "Best fit: type 2 adds a row per version with start and end columns, so any past date can be answered.", "Works, but a nightly snapshot overwrite loses every change made between two snapshots."]}, {"id": "s9-02", "type": "single", "skill": "S9 · Data Modeling", "stem": "Fifty dashboards recompute monthly revenue by region from a very large sales fact table, and each run is slow. Results may be up to a day old. The team has no spare engineer to own another pipeline, and wants the platform to keep the stored result current. What should they build?", "options": ["A larger SQL warehouse, such as Large instead of Medium, kept running for the dashboards at peak hours", "A gold Delta table rebuilt each morning by a scheduled job that writes the monthly regional aggregate", "A standard view that holds the aggregation query, reused by every dashboard in the workspace", "A materialized view that stores the monthly regional aggregate, refreshed by the platform"], "answer": 3, "runner": 1, "runnerWhy": "a scheduled gold table wins when the team already runs jobs and wants full control over the load logic and table layout.", "think": {"premise": "That a shared definition or more compute equals a speed-up. Only stored results remove the recomputation, and the choice is who keeps them current.", "map": [["Same heavy aggregate repeated, no owner for a pipeline", "Platform-managed pre-computation", "Materialized view"], ["Team already runs jobs, wants control of load logic", "Hand-built gold table", "Scheduled job writing a Delta table"], ["Small data, always live", "Freshness", "Standard view"]], "apply": [["\"recompute monthly revenue\"", "Repeated work is what a stored result avoids, which rules out the standard view and the bigger warehouse."], ["\"no spare engineer to own another pipeline\"", "The platform must maintain the result, which rules out the hand-built job."]], "rule": "Pre-compute the shared aggregation; if nobody can own a pipeline, let a materialized view do it.", "guide": "Design dimensional models for analytical workloads, leveraging Materialized Views for pre-computed aggregation and Unity Catalog Metric Views for governed, reusable metric definitions, to ensure efficient querying and aggregation."}, "eli5": "Write the answer on the wall instead of redoing the sum each time, and hire the wall to keep it fresh.", "learn": "https://docs.databricks.com/aws/en/views/materialized", "why": ["Works, but it pays for the same repeated scans at a higher size.", "Works, but the team must write, schedule and monitor the job that keeps the table current.", "Works, but a standard view runs the full query every time, so dashboards stay slow.", "Best fit: a materialized view stores the result and the platform refreshes it, incrementally when possible."]}, {"id": "s5-08", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A query profile shows pruning is fine, but one join operator produces far more rows than either input and then triggers a large shuffle. Compute size looks adequate. What should the engineer check first?", "options": ["Whether the disk cache is enabled on the workers that run the join", "Whether the warehouse can be doubled in size to absorb the rows", "Whether the table should be repartitioned by date columns before the join", "Whether the join keys are unique on the intended lookup side"], "answer": 3, "runner": 1, "runnerWhy": "more compute can absorb the load and is right when the row counts are as expected, but here the profile shows an unexpected row explosion.", "think": {"premise": "That heavy shuffles are a sizing issue. Rows exploding at a join often mean duplicate keys.", "map": [["Output rows far above inputs", "Join keys", "Fix duplicates or the condition"], ["Low file pruning", "Layout", "Cluster on filters"], ["Correct counts, slow tasks", "Compute", "Scale up"]], "apply": [["\"far more rows than either input\"", "Duplicate keys or a missing condition."], ["\"pruning is fine\"", "Rules out layout."]], "rule": "A join that creates rows is a data problem, not a cluster problem.", "guide": "Use the query profile to identify performance bottlenecks, such as data-skipping inefficiencies, join strategies, and shuffle operations."}, "eli5": "Two guest lists with repeated names make every table seat too many people.", "learn": "https://docs.databricks.com/aws/en/sql/user/queries/query-profile", "why": ["Works, but caching affects file reads, not join output.", "Works, but it pays more to process rows that should not exist.", "Works, but pruning is already fine and repartitioning adds another shuffle.", "Best fit: unexpected row growth at a join points to non-unique keys or a missing condition."]}, {"id": "s1-a05", "type": "single", "skill": "S1 · Developing Code", "stem": "Partner systems drop new CSV files into cloud storage all day. Each file must be loaded once into a Delta table, nothing may be loaded twice after a restart, and new columns will appear over time. The team wants the least custom code. What should they build?", "options": ["A pipeline that reads the folder with a plain file stream and an explicit checkpoint", "A job that records loaded file names in a control table and skips those on each run", "A Lakeflow pipeline that reads the folder with Auto Loader into a streaming table", "A job that lists the folder hourly and loads every file with a batch read and a merge"], "answer": 2, "runner": 0, "runnerWhy": "a plain file stream with a checkpoint also works, but Auto Loader adds schema handling and cheaper file discovery; it wins if files were few and the schema fixed.", "think": {"premise": "That reading new files means tracking file names yourself. Auto Loader already keeps that state in its checkpoint.", "map": [["Files arriving continuously", "Source type", "Auto Loader (cloudFiles)"], ["Load each file once after restarts", "State", "Checkpoint file tracking, exactly-once"], ["New columns over time", "Schema drift", "Auto Loader schema handling and rescue"], ["Very few files, fixed schema", "Simple case", "A plain file stream is enough"]], "apply": [["\"loaded once ... nothing may be loaded twice\"", "Needs tracked file state, which Auto Loader provides."], ["\"new columns will appear over time\"", "Rules out a plain file stream for schema change."]], "rule": "Arriving files into a table means Auto Loader in a pipeline, not hand-built file bookkeeping.", "guide": "Create production-ready data pipelines for streaming data using Lakeflow Pipelines and Auto Loader."}, "eli5": "A doorman with a guest list, instead of you checking every face yourself each hour.", "learn": "https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/", "why": ["Works, but a plain stream gives no file-level schema evolution and no scalable file discovery.", "Works, but a control table is bookkeeping you must write, test and keep consistent with the load.", "Best fit: Auto Loader tracks seen files and handles schema change, and the pipeline manages checkpoints.", "Works, but hourly listing and merging means your own state handling and a delay of up to an hour."]}, {"id": "s9-01", "type": "single", "skill": "S9 · Data Modeling", "stem": "A managed order-lines table holds billions of rows at one row per order line. Queries join to customers and filter by customer id, and streaming writes leave many small files. Which layout plan fits?", "options": ["Cluster on the customer id and let Predictive Optimization compact small files", "Partition by order date and Z-order by customer id each night", "Partition by customer id and compact files with a weekly OPTIMIZE job", "Leave the table unorganised and rely on larger cluster sizes for joins"], "answer": 0, "runner": 2, "runnerWhy": "partitioning by date works if downstream jobs always handle whole days and retention is by day.", "think": {"premise": "That the main filter column should become the partition. A high-cardinality join key is a clustering key.", "map": [["Filter and join on a high-cardinality key", "Relationship access", "Cluster on that key"], ["Retention or loads by whole day", "Grain", "Partition by date"], ["Many small files", "Compaction", "OPTIMIZE, automatically via Predictive Optimization"]], "apply": [["\"filter by customer id\"", "The access pattern the clustering key should match."], ["\"many small files\"", "Compaction must be part of the plan."]], "rule": "Cluster on the keys queries use, partition only on low-cardinality grain, and keep compacting.", "guide": "Design scalable Delta/Iceberg table layouts for large data assets by mapping partitioning to data grain, aligning clustering to relationship access patterns, and maintaining balanced file sizes through compaction."}, "eli5": "Sort the mail by street, not by giving each resident a separate room.", "learn": "https://docs.databricks.com/aws/en/delta/clustering", "why": ["Best fit: clustering matches the customer access pattern and automatic compaction keeps files balanced.", "Works, but date partitions do not match customer filters and Z-order is not combined with newer clustering.", "Works, but millions of customer partitions create tiny files and heavy metadata.", "Works, but bigger clusters pay to read files a layout would skip."]}, {"id": "s1-a07", "type": "single", "skill": "S1 · Developing Code", "stem": "A pipeline ingests clickstream events that are only ever appended, and must hold them cheaply with each update reading only new events. A second table must show daily revenue per product from an orders table whose rows are corrected after the fact. Which pairing is best?", "options": ["A materialized view for the clickstream and a streaming table for the revenue table", "A materialized view for both, on classic compute so each refresh is fully recomputed", "A streaming table for the clickstream and a materialized view for the revenue table", "A streaming table for both, with a full refresh scheduled each night for the revenue"], "answer": 2, "runner": 1, "runnerWhy": "a materialized view for both is a sound design on serverless compute, where refresh is incremental; this option names classic compute, which recomputes fully on each refresh, so it only competes if the compute changes.", "think": {"premise": "That the two table types are interchangeable. A streaming table promises append-only input; a materialized view follows its query even when inputs change.", "map": [["Append-only events, read only new rows", "Streaming table", "Ingest into a streaming table"], ["Source rows corrected, aggregated results", "Materialized view", "Define by query so changes flow in"], ["Materialized view on classic compute", "Full recompute", "Serverless gives incremental refresh"], ["Updates feeding a streaming table", "Unsupported input", "Switch the downstream to a materialized view"]], "apply": [["\"only ever appended\"", "Fits a streaming table and each update reads only new events."], ["\"rows are corrected after the fact\"", "Streaming tables expect appends, so the revenue table is a materialized view."]], "rule": "Append-only and cheap means streaming table; corrected inputs and aggregates mean materialized view.", "guide": "Choose between a streaming table and a materialized view for a given latency, cost, and refresh requirement."}, "eli5": "A guest book only gets new lines; a scoreboard is redrawn from the latest results.", "learn": "https://docs.databricks.com/aws/en/ldp/transform", "why": ["Works, but the roles are reversed, so a streaming table would meet changed rows it does not expect.", "Works, but full recompute of the clickstream on each refresh costs more than reading new events.", "Best fit: appends suit a streaming table, and corrected orders need a view that follows its query.", "Works, but a nightly full refresh throws away the streaming table's advantage and is a heavy fix."]}, {"id": "s1-a04", "type": "single", "skill": "S1 · Developing Code", "stem": "A data scientist's row-by-row Python UDF scores 80 million rows a night and runs for hours. The scoring uses numeric operations on two columns, and a lookup table must be loaded once per batch of work. Which change fits best?", "options": ["Convert it to a SQL UDF with a CASE expression that reproduces each of the scoring rules", "Keep the row-by-row function and raise the number of shuffle partitions on the job", "Rewrite it as an iterator-style pandas UDF that loads the lookup once and scores whole batches", "Rewrite it as a Unity Catalog Python UDF so it is governed and can be shared by name across jobs"], "answer": 2, "runner": 3, "runnerWhy": "a Unity Catalog function is the right pick for sharing and grants, but it does not change the cost of row-at-a-time work; it wins if the stem asked for governance.", "think": {"premise": "That a faster UDF means more compute. Row-at-a-time calls pay overhead per row; batches through Arrow pay it per batch.", "map": [["Row-by-row Python UDF is slow", "Per-row overhead", "Pandas UDF on batches"], ["Costly setup such as a lookup load", "Repeated work", "Iterator of Series form loads once"], ["Logic is numeric on columns", "Vectorizable", "pandas or built-in functions"], ["Need sharing and grants", "Governance", "Unity Catalog function; the runner-up wins"]], "apply": [["\"row-by-row Python UDF\"", "Names the per-row overhead to remove."], ["\"a lookup table must be loaded once per batch\"", "Points to the iterator form of the pandas UDF."]], "rule": "For speed, move from rows to batches; for setup that should happen once, use the iterator form.", "guide": "Develop User-Defined Functions (UDFs) using Pandas, Python, and SQL, including Unity Catalog functions for the given constraints."}, "eli5": "Carrying bricks one at a time is slow; use a wheelbarrow, and fetch the wheelbarrow once.", "learn": "https://docs.databricks.com/aws/en/udf/pandas", "why": ["Works, but a long CASE expression may not express the scoring and the lookup load is lost.", "Works, but more partitions add parallelism without removing the per-row call overhead.", "Best fit: batches move through Arrow and the iterator form loads the lookup once per task.", "Works, but registration in Unity Catalog adds governance and does not remove per-row overhead."]}, {"id": "s4-05", "type": "single", "skill": "S4 · Monitoring and Alerting", "stem": "A retailer's nightly job always finishes green, yet last week an upstream change halved the daily order count and nobody noticed for three days. The on-call analyst should be told within an hour of the next drop below a set level. What should you build?", "options": ["A dashboard of daily order counts, refreshed on a schedule, that the analyst checks each morning", "An email notification on the job that fires whenever a run fails, with the run link included", "A job timeout of three hours so that runs taking too long are stopped and reported", "A scheduled alert on a query that returns the daily order count, notifying the analyst"], "answer": 3, "runner": 1, "runnerWhy": "failure notifications are a recommended practice and would win if the problem were a run failing, but this job succeeds.", "think": {"premise": "That a green run means correct data. A run can succeed while the numbers are wrong, so the business number itself needs a check.", "map": [["Run succeeds, metric wrong", "Query-based alert", "Alert on the metric with a schedule"], ["Run fails or exceeds expected time", "Job notifications", "Configure on the job"], ["A later task must skip on a check", "Alert as a job task", "Branch on the result"]], "apply": [["\"always finishes green\"", "Rules out failure notifications."], ["\"told within an hour\"", "A scheduled check with a notification, not a manual look."]], "rule": "When the problem is a wrong number rather than a failed run, alert on the number.", "guide": "Use Databricks Lakehouse alerts to monitor governed business metrics, data quality and anomaly signals, usage and cost, SQL warehouse/query health, audit and security events, AI agent quality, and Lakeflow Job branching."}, "eli5": "A smoke alarm for the number, not only a lock on the door.", "learn": "https://docs.databricks.com/aws/en/sql/user/alerts/", "why": ["Works, but a dashboard relies on a person looking, so a drop can still go unseen for days.", "Works, but it stays silent because the run succeeds even when the data is wrong.", "Works, but a timeout reacts to slow runs and these runs are not slow.", "Best fit: the alert evaluates the metric on a schedule and notifies when the condition is met."]}, {"id": "s6-03", "type": "single", "skill": "S6 · Security and Compliance", "stem": "An analytics team joins a loyalty table to a purchases table on customer_id, and counts customers by birth year. They must not see raw customer ids or full birth dates. The privacy team wants one protection that still lets the join and the counts work. What should you apply?", "options": ["A column mask that returns a random value on every read of customer_id, keeping birth_date unchanged", "A row filter that hides all customers whose birth year is before 1960 from the analysts, using a filter function", "A column mask that returns NULL for both customer_id and birth_date for analysts, applied with ALTER TABLE SET MASK", "A salted SHA-256 hash mask on customer_id and a mask on birth_date that returns only the year"], "answer": 3, "runner": 2, "runnerWhy": "returning NULL is real suppression and is the strongest choice when the column is never needed for joins or grouping.", "think": {"premise": "That the strongest protection is always best. The right method keeps the analytic use alive: hashing keeps a consistent join key, generalization keeps a usable birth year.", "map": [["Value needed as a join key", "Hashing with a salt", "Consistent output so joins match"], ["Value needed only roughly", "Generalization", "Reduce precision, such as year instead of date"], ["Value never needed", "Suppression", "Return NULL; wins when no analysis uses it"]], "apply": [["\"joins ... on customer_id\"", "Rules out NULL and random values, which break matching."], ["\"counts customers by birth year\"", "Year is enough, so full dates can be generalized."], ["\"must not see raw customer ids\"", "Rules out leaving the id unchanged."]], "rule": "Pick the weakest method that still hides the value and keeps the analysis working.", "guide": "Apply anonymization and pseudonymization methods — such as hashing, tokenization, suppression, and generalization — to confidential data (e.g., using column masks and related Unity Catalog features)."}, "eli5": "You swap names for code names on a seating chart: everyone can still see who sits next to whom, but nobody learns who is who.", "learn": "https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/", "why": ["Works, but random output changes each read, so the same customer never matches across tables.", "Works, but a row filter hides people instead of protecting values, and it biases the counts.", "Works, but NULL ids make every join key identical and empty, so the analysis stops working.", "Best fit: the salted hash keeps one stable key per customer for the join, and the year keeps the counts correct."]}, {"id": "s9-03", "type": "single", "skill": "S9 · Data Modeling", "stem": "Three teams report net revenue from the same sales tables and get different totals because each applies its own refund rules. The company wants one governed definition that any dimension can slice. What should they create?", "options": ["A wiki page describing the agreed formula and grouping for analysts to follow in reports", "A Unity Catalog metric view that defines net revenue once, with its dimensions and filters", "A shared SQL function in Unity Catalog that each report calls with its own filters", "A materialized view named net_revenue that each team copies and edits for its own reports"], "answer": 1, "runner": 3, "runnerWhy": "a materialized view wins when the problem is speed over a fixed grouping, rather than a single shared definition.", "think": {"premise": "That a stored table is a governed metric. A metric view defines measures and dimensions once.", "map": [["Teams disagree on a definition", "Governance", "Metric view"], ["Repeated heavy aggregation", "Speed", "Materialized view"], ["Fixed grouping, small data", "Simplicity", "Standard view"]], "apply": [["\"one governed definition\"", "Points to a metric view."], ["\"any dimension can slice\"", "Metric views allow grouping by any defined dimension."]], "rule": "A metric view fixes the meaning of a number; a materialized view fixes its speed.", "guide": "Design dimensional models for analytical workloads, leveraging Materialized Views for pre-computed aggregation and Unity Catalog Metric Views for governed, reusable metric definitions, to ensure efficient querying and aggregation."}, "eli5": "One agreed recipe card that every kitchen cooks from.", "learn": "https://docs.databricks.com/aws/en/metric-views/", "why": ["Works, but documentation is not enforced by the platform.", "Best fit: a metric view stores the measure and its dimensions once in Unity Catalog for all tools.", "Works, but callers can still pass different filters and the definition is not tied to dimensions.", "Works, but copies and edits drift apart again, and it fixes one grouping."]}, {"id": "s1-b02", "type": "single", "skill": "S1 · Developing Code", "stem": "A three-person team must run forty dependent streaming and batch tables from raw files to reporting tables. They have no one to manage run order, retries or parallelism, and every table is written in SQL or Python as a plain definition. Which approach fits best?", "options": ["Write forty Structured Streaming queries and schedule each one as its own Lakeflow Jobs task", "Run one large Structured Streaming application that holds all forty queries in one notebook", "Write one Structured Streaming query per layer and chain them with manually managed checkpoints", "Define the tables in a Lakeflow Pipeline and let it order, parallelize and retry the flows itself"], "answer": 3, "runner": 0, "runnerWhy": "hand-written Structured Streaming gives full control, and it wins when the logic needs low-level control, such as a custom stateful operator.", "think": {"premise": "That raw Structured Streaming is the more serious choice. It leaves orchestration, retries and checkpoint locations with you.", "map": [["Many dependent tables, small team", "Who owns orchestration", "Pipelines work out order and retries"], ["Custom low-level query logic", "Control needed", "Structured Streaming"], ["Plain table definitions", "Declarative fit", "Pipelines"]], "apply": [["\"no one to manage run order, retries or parallelism\"", "The pipeline engine does exactly this; rules out the hand-built options."], ["\"a plain definition\"", "Nothing needs low-level control, so the runner-up loses."]], "rule": "When the work is many dependent tables and few people, declare the tables and let the pipeline run them.", "guide": "Choose between Spark Structured Streaming and Apache Spark™ Declarative Pipelines for scalable ETL given operational constraints."}, "eli5": "Give a recipe list to a kitchen that plans the order itself, instead of timing every pot yourself.", "learn": "https://docs.databricks.com/aws/en/ldp/concepts", "why": ["Works, but the team still owns forty queries, their schedules, their retries and their checkpoint paths.", "Works, but one shared application is a single point of failure and the team still orders and restarts queries by hand.", "Works, but chaining layers by hand leaves ordering, retries and checkpoint upkeep with a team that has no time for them.", "Best fit: the pipeline reads the dependencies, orders and parallelizes flows, and retries failures for you."]}, {"id": "s1-b04", "type": "single", "skill": "S1 · Developing Code", "stem": "A serverless Lakeflow Jobs task calls a payments service that charges a card. The charge is not idempotent, so Databricks must not retry the task on its own after a failure. Everything else about the job is fine. What should you change?", "options": ["Switch the job to standard performance mode by turning off Performance optimized", "Uncheck serverless auto-optimization in the task's retry policy dialog", "Set the job's maximum concurrent runs to one so that runs never overlap in time", "Add a failure notification so an engineer reviews every failed run of this task"], "answer": 1, "runner": 0, "runnerWhy": "standard performance mode lowers cost for jobs that tolerate a slower start; it wins when the goal is cheaper runs, not run-once behavior.", "think": {"premise": "That performance mode and retries are one setting. Auto-optimization, which may add retries, is switched off in the retry policy; performance mode only trades startup speed for cost.", "map": [["Must execute at most once", "Auto-optimization", "Disable it in the retry policy"], ["Cheaper run, slow start fine", "Performance mode", "Standard mode"], ["Need to know about failures", "Notifications", "Alert a person; retries are unchanged"]], "apply": [["\"must not retry the task on its own\"", "Points to the retry policy and auto-optimization."], ["\"after a failure\"", "Rules out concurrency limits, which only stop overlapping runs."]], "rule": "When a task is not safe to repeat, turn off serverless auto-optimization in its retry policy.", "guide": "Choose appropriate compute and configuration for environments and dependencies — including serverless compute (serverless environments, dependency management, performance mode), high-memory notebook tasks, and auto-optimization settings (e.g., disallowing retries)."}, "eli5": "Tell the helper not to quietly redo a job that cannot be undone.", "learn": "https://docs.databricks.com/aws/en/jobs/run-serverless-jobs", "why": ["Works, but standard mode only trades start speed for cost and does not change retries.", "Best fit: the docs say to disable auto-optimization, which may add retries, for tasks that must run at most once.", "Works, but limiting concurrent runs stops overlap and does not prevent a retry of the same run.", "Works, but a notification only tells a person after the failure and retries still happen."]}, {"id": "s3-06", "type": "single", "skill": "S3 · Data Manipulation", "stem": "A pipeline loads card payments. Rows with a null account id appear occasionally. The business wants good rows to keep flowing, bad rows kept somewhere for the finance team to review, and no manual step per run. How should you apply expectations?", "options": ["Set the rule to drop and read the count of dropped rows from the pipeline event log", "Leave the default warn action on the rule and filter nulls out in every later query", "Keep the main table's rule as drop, and fill a second table with rows that fail the same rule", "Set the rule to fail update, so any bad row stops the run until someone repairs the source"], "answer": 2, "runner": 0, "runnerWhy": "drop with its logged count is right when nobody needs the rows back; here finance wants to review them, which a count cannot give.", "think": {"premise": "That drop saves bad rows somewhere. Dropped rows are excluded and only counted, so keeping them needs a separate quarantine table.", "map": [["Bad rows must be reviewed", "Pattern", "Quarantine table from the inverse condition"], ["Only a count is needed", "Where the runner-up wins", "Plain drop"], ["One bad row makes output wrong", "Action", "Fail update"]], "apply": [["\"bad rows kept somewhere for the finance team\"", "Needs a quarantine, not only a drop count."], ["\"good rows to keep flowing\"", "Rules out fail update."]], "rule": "Drop discards, fail stops, quarantine keeps: pick by what the business does with bad rows.", "guide": "Implement data quality expectations in Lakeflow Pipelines to quarantine, drop, or fail on bad records."}, "eli5": "Put the damaged parcels in a separate bin for inspection instead of throwing them out or closing the factory.", "learn": "https://docs.databricks.com/aws/en/ldp/expectations", "why": ["Works, but dropped rows are not stored anywhere; only a count remains, so finance cannot review them.", "Works, but warn keeps bad rows in the main table, so every consumer must remember to filter.", "Best fit: the main table gets only valid rows and a second table keeps the failing rows for review.", "Works, but a single bad row stops the update and blocks all good data."]}, {"id": "s1-a01", "type": "single", "skill": "S1 · Developing Code", "stem": "A retailer's team keeps the same cleaning logic copied across five notebooks. They want unit tests that run in a pull request, and the identical code promoted from a dev workspace to prod by an automated pipeline. How should they restructure the project?", "options": ["Store the shared code in a Git folder and have each job clone the latest main branch", "Move the logic into a Python package and let the bundle build it as a wheel for each target", "Keep the notebooks but import shared code from one common workspace folder in every task, by path", "Paste the shared logic into a single large notebook and call it with run from each task"], "answer": 1, "runner": 2, "runnerWhy": "it removes the copies, but workspace paths cannot be unit tested outside Databricks or promoted as one versioned artifact; it wins if tests and promotion were not required.", "think": {"premise": "That sharing code between notebooks is the same as packaging it. A package is a unit you can version, test anywhere and deploy identically.", "map": [["Same logic copied in many places", "Duplication", "Extract into an installable package"], ["Tests must run in a pull request", "Testability", "Package imports with no workspace needed"], ["Same code to dev then prod", "Promotion", "Bundle artifacts of type whl, one target per environment"], ["Short exploratory glue, no tests", "Over-engineering", "Plain notebook tasks are enough"]], "apply": [["\"unit tests that run in a pull request\"", "Needs code importable outside the workspace, ruling out workspace-folder imports."], ["\"the identical code promoted from a dev workspace to prod\"", "Needs one built, versioned artifact, ruling out cloning main per run."]], "rule": "When code must be tested and promoted as a unit, make it a package and let the bundle build and deploy it.", "guide": "Implement scalable Python project structures for Declarative Automation Bundles (formerly Databricks Asset Bundles / DABs) to support modular development and CI/CD integration."}, "eli5": "Instead of photocopying the recipe into five cookbooks, publish it once as a book every kitchen orders by edition.", "learn": "https://docs.databricks.com/aws/en/dev-tools/bundles/python-wheel", "why": ["Works, but cloning the latest main on each run means prod runs unreviewed, unpinned code.", "Best fit: one versioned wheel is built by the bundle, tested in the pull request and deployed unchanged to each target.", "Works, but workspace-folder imports cannot be tested outside Databricks and carry no version to promote.", "Works, but one large notebook is still hard to unit test and keeps all logic coupled together."]}, {"id": "s5-07", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A daily query on a large table is slow. Its query profile shows one scan reading nearly every file even though the query filters on a single store id, and the other operators look healthy. What is the most likely fix?", "options": ["Increase the shuffle partition count to spread the scan wider", "Cluster the table on the store id so data skipping can prune files", "Broadcast the dimension table to avoid the join shuffle", "Raise the SQL warehouse to a much larger size to scan the files faster"], "answer": 1, "runner": 3, "runnerWhy": "a bigger warehouse does speed the scan and helps if pruning is already good and the query is simply large.", "think": {"premise": "That a slow scan needs more compute. The profile shows whether files are being skipped.", "map": [["Scan reads almost all files despite a filter", "Data layout", "Cluster on the filter column"], ["Pruning good, time spread evenly", "Compute", "Larger warehouse"], ["Huge shuffle in a join", "Join strategy", "Broadcast or fix keys"]], "apply": [["\"reading nearly every file\"", "Low pruning means the layout ignores the filter."], ["\"other operators look healthy\"", "Rules out joins and shuffles."]], "rule": "A filter that skips nothing is a layout problem, not a compute problem.", "guide": "Use the query profile to identify performance bottlenecks, such as data-skipping inefficiencies, join strategies, and shuffle operations."}, "eli5": "Sorting a library by author when everyone asks by shelf number.", "learn": "https://docs.databricks.com/aws/en/sql/user/queries/query-profile", "why": ["Works, but shuffle partitions do not affect an under-pruned scan and other operators are healthy.", "Best fit: low file pruning on a selective filter points to a layout that does not match the filter.", "Works, but there is no join problem in the profile.", "Works, but it pays for more compute and still reads every file."]}, {"id": "s2-02", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "A payments team reads card events from a Kafka topic into a Lakeflow Pipeline. The pipeline's first transformation produces garbage text for the event body, although the broker connection and topic name are correct. The team has not changed any broker settings. What is the most likely fix?", "options": ["Cast or decode the binary value column, for example to a string or with from_avro", "Add a Kinesis source in parallel so the events arrive in a text-friendly format", "Set startingOffsets to earliest so the full history of the topic is read first", "Raise the number of partitions on the topic so each message is split into smaller parts"], "answer": 0, "runner": 2, "runnerWhy": "reading from the start is a real setting for backfills, but it changes which messages you read, not how the bytes are shown.", "think": {"premise": "That a connected Kafka source hands you readable text. Kafka keys and values always arrive as binary and must be cast or decoded.", "map": [["Connection works, body looks wrong", "Data type of value", "Cast to string or decode Avro or JSON"], ["Need old messages as well", "Starting position", "startingOffsets earliest"], ["Messages missing, not garbled", "Where the runner-up wins", "Check offsets and topic, not the cast"]], "apply": [["\"connection and topic name are correct\"", "Rules out connection options."], ["\"produces garbage text for the event body\"", "Points at an undecoded binary value, not at missing data."]], "rule": "Kafka gives you bytes; decode the value before you use it.", "guide": "Develop data ingestion pipelines to ingest a variety of data formats, including Delta Lake, Parquet, JSON, Iceberg, CSV, and Binary from diverse sources such as message buses (Kafka, Kinesis, Pub/Sub) and cloud storage."}, "eli5": "The parcel arrived fine, but it is still sealed; you have to open it to read the letter.", "learn": "https://docs.databricks.com/aws/en/connect/streaming/kafka", "why": ["Best fit: the Kafka source returns key and value as binary, so the body needs a cast or a decoder.", "Works, but a second bus is unrelated to the body being undecoded and duplicates the events.", "Works, but earliest only changes which messages are read, and the bytes would still be undecoded.", "Works, but partition counts affect parallelism and never change how a message body is encoded."]}, {"id": "s7-02", "type": "single", "skill": "S7 · Data Governance", "stem": "A team lead is granted SELECT on the schema finance.reports, and holds USE CATALOG on finance and USE SCHEMA on that schema. Next week a pipeline adds a new table to finance.reports. The lead queries it and wants to know why it works. What is the reason?", "options": ["Tables created by a pipeline get SELECT for any user holding USE SCHEMA on the parent schema of that table", "Privileges granted on a schema apply to its current and future tables, so the new table inherits SELECT", "Unity Catalog re-reads every grant nightly and copies the schema grants onto each table that exists at that time", "The lead gained access because the pipeline's owner is in the same group as the lead in the workspace"], "answer": 1, "runner": 2, "runnerWhy": "a nightly copy is an invented mechanism, but a per-table grant would win if the lead had to be kept out of this table.", "think": {"premise": "That a grant covers only the objects present when it was made. Grants on containers flow to current and future children.", "map": [["Grant on a catalog or schema", "Inheritance to children", "Covers existing and future objects"], ["Needs to exclude one table", "Schema grant too wide", "Use table-level grants"], ["SELECT without usage rights", "Access still fails", "USE CATALOG and USE SCHEMA are also needed"]], "apply": [["\"granted SELECT on the schema\"", "The level of the grant decides the reach."], ["\"adds a new table\"", "Future objects are covered by inheritance."]], "rule": "A grant lands at the level you granted and flows down to everything below, now and later.", "guide": "Demonstrate understanding of the Unity Catalog permission inheritance model as a mechanism for managing access control across catalogs, schemas, and objects."}, "eli5": "Giving someone a key to the floor opens every room on it, including rooms built next month.", "learn": "https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges", "why": ["Works, but USE SCHEMA gives no data access by itself, so it could not explain the access.", "Best fit: schema-level privileges are inherited by current and future child objects.", "Works, but there is no nightly copy job; inheritance is evaluated when access is checked.", "Works, but group membership of the pipeline owner is unrelated to the lead's grant."]}, {"id": "s3-04", "type": "single", "skill": "S3 · Data Manipulation", "stem": "A table has a VARIANT column named payload. A query reads the amount with payload:amount::double, but one bad record holds the text 'n/a' there and the whole query fails with a cast error. The team wants the query to continue and return NULL for such rows. What should you change?", "options": ["Read the amount with try_variant_get, using the path and the double type", "Wrap the query in a retry loop so the failed task is run again after a delay", "Drop the bad record from the source table before every run of the query", "Convert the column to a JSON string first and use get_json_object for the amount"], "answer": 0, "runner": 2, "runnerWhy": "cleaning the source is a reasonable data practice, but it hand-fixes data instead of letting the query tolerate bad values.", "think": {"premise": "That a failed cast needs data cleanup. try_variant_get returns NULL when the cast fails, so the query keeps running.", "map": [["Cast error on a variant field", "Function", "try_variant_get returns NULL on failure"], ["Wrong value must be rejected loudly", "Where the runner-up wins", "Keep the strict cast so errors surface"], ["Field names not matching", "Case sensitivity", "Names are case sensitive"]], "apply": [["\"whole query fails with a cast error\"", "The strict cast is the cause."], ["\"return NULL for such rows\"", "Exactly what try_variant_get does."]], "rule": "Use try_variant_get when casts may fail and NULL is acceptable.", "guide": "Develop a model and query semi-structured data using the VARIANT data type and related functions (e.g., parse_json, variant_get)."}, "eli5": "A forgiving form that leaves a box blank when the answer is unreadable, rather than refusing the whole page.", "learn": "https://docs.databricks.com/aws/en/semi-structured/variant", "why": ["Best fit: try_variant_get yields NULL when the cast fails, so good rows still return.", "Works, but a retry repeats the same cast on the same bad value and fails again.", "Works, but it changes the data by hand every time and leaves the query fragile for the next bad value.", "Works, but it discards the variant type and reparses text, and still needs a safe cast."]}, {"id": "s8-06", "type": "single", "skill": "S8 · Debugging and Deploying", "stem": "Production notebooks must match the main branch after each merged pull request. Nobody should edit code by hand in production. The team uses an external CI system and a service principal. What should the team set up?", "options": ["A production Git folder tracking main, updated by the service principal on merge", "A shared folder where developers pull the main branch whenever they release to production", "Notebook exports to a storage volume, imported into production by an engineer each release", "A scheduled job in each developer's folder that copies notebooks to production nightly"], "answer": 0, "runner": 1, "runnerWhy": "a developer-driven pull is common and would win in a small team with no CI, but here it allows hand edits.", "think": {"premise": "That production should be pulled by whoever ships. Production folders are best updated only by automation on merge.", "map": [["Production must follow a branch", "Production Git folder", "Update by service principal on merge"], ["Jobs and pipelines change too", "Bundle", "Deploy with the CLI"], ["Developer work", "Own folder on a branch", "Push and open a pull request"]], "apply": [["\"Nobody should edit code by hand in production\"", "Only automation updates the folder."], ["\"external CI system and a service principal\"", "The automation identity exists."]], "rule": "Production Git folders follow a deployment branch and are updated by automation, not by people.", "guide": "Configure Git-based CI/CD workflows using Databricks Git folders (formerly Repos) to deploy notebooks and code."}, "eli5": "Only the delivery van restocks the shelf, not the shoppers.", "learn": "https://docs.databricks.com/aws/en/repos/ci-cd-techniques-with-repos", "why": ["Best fit: the folder tracks the branch and only the automation identity updates it.", "Works, but people trigger the pull, so unreviewed or hand-made changes can still reach production.", "Works, but manual exports and imports are slow and drift from the branch.", "Works, but copying from personal folders skips review and ties production to one person's work."]}, {"id": "s1-b05", "type": "single", "skill": "S1 · Developing Code", "stem": "An engineer has a long notebook that adds a loyalty tier column to orders. The team wants fast tests in CI that use no production data and compare both values and column types. How should the logic be tested?", "options": ["Run the notebook against a copy of the production orders table and check the row count", "Wrap it in a function and test it with assertDataFrameEqual and assertSchemaEqual in pytest", "Run the whole job in a staging workspace and review the output table by eye after each run", "Collect the result to the driver and compare it to a Python list with plain asserts"], "answer": 1, "runner": 0, "runnerWhy": "a staging run is a real integration test, and it wins when the risk is in how systems connect rather than in the function logic.", "think": {"premise": "That a row count proves a transformation is right. A count passes when values or types are wrong.", "map": [["Logic in one function", "Unit test", "Small input, expected DataFrame, assertDataFrameEqual"], ["Column names or types matter", "Schema check", "assertSchemaEqual"], ["Risk is in system wiring", "Integration test", "Run against staging data"]], "apply": [["\"fast tests in CI that use no production data\"", "Rules out production copies and staging runs."], ["\"compare both values and column types\"", "Needs the DataFrame and schema assert helpers, not a count."]], "rule": "Test the function on tiny made-up data, and compare values and schema with the assert helpers.", "guide": "Develop unit and integration tests using assertDataFrameEqual, assertSchemaEqual, DataFrame.transform, and testing frameworks to ensure code correctness."}, "eli5": "Test one gear on the bench before you test the whole watch.", "learn": "https://docs.databricks.com/aws/en/notebooks/testing", "why": ["Works, but a production copy is slow, breaks the no-production-data rule, and a count misses wrong values.", "Best fit: a small input and an expected result run in seconds, with values and schema both checked.", "Works, but a staging run is slow for CI and a human reading output misses small errors.", "Works, but list comparison breaks on row order and float rounding, and it says nothing about column types."]}, {"id": "s5-09", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A new fact table will grow quickly past several terabytes. It is filtered by a customer id with millions of distinct values, and analysts expect to add new filter columns over time. Which layout should the team choose?", "options": ["Liquid Clustering on the customer id, with keys that can be changed later", "Partitioning by load date, then ZORDER by customer id on every run", "Partitioning by customer id so that each customer's data is isolated", "No layout at all, relying on file compaction and bigger clusters alone"], "answer": 0, "runner": 2, "runnerWhy": "date partitioning with ZORDER works and is the right design when whole days are always read or dropped and tooling depends on date folders.", "think": {"premise": "That partitioning is always the first layout choice. For high-cardinality filters and shifting patterns Databricks recommends Liquid Clustering.", "map": [["High-cardinality filter, changing patterns", "Layout", "Liquid Clustering"], ["Low-cardinality column always filtered, retention by day", "Layout", "Partitioning"], ["Existing ZORDER table", "Legacy", "Migrate to clustering if rewriting is acceptable"]], "apply": [["\"millions of distinct values\"", "Partitioning would create millions of folders."], ["\"add new filter columns over time\"", "Clustering keys can change without rewriting data."]], "rule": "High cardinality and changing filters mean cluster, do not partition.", "guide": "Compare Liquid Clustering vs partitioning/ZORDER for a given table size and query pattern."}, "eli5": "Labeling shelves you can relabel later instead of building walls.", "learn": "https://docs.databricks.com/aws/en/delta/clustering", "why": ["Best fit: Liquid Clustering handles high-cardinality filters and keys can be changed later.", "Works, but changing the filter pattern later means rewriting, and the two techniques need maintenance runs.", "Works, but millions of customer folders cause tiny files and a costly metadata load.", "Works, but compaction alone does not order data, so filters skip little."]}, {"id": "s1-a06", "type": "single", "skill": "S1 · Developing Code", "stem": "A job built in the UI must now be created identically in the staging and production workspaces by a release script, and run once after creation. The team wants the job to be saved so it appears in the Jobs list and retries on failure. What should the script do?", "options": ["Call jobs submit with the JSON definition so each release runs the work once directly", "Call jobs reset on the new workspace with the full job JSON, then trigger the run", "Export the job as a screenshot of its settings and have an engineer recreate it by hand", "Call jobs create with a JSON definition, then jobs run-now with the returned job id"], "answer": 3, "runner": 1, "runnerWhy": "reset overwrites all settings of an existing job, so it suits updates after the job exists; it would win if the job already existed and had to be changed.", "think": {"premise": "That every way of running a job from code behaves the same. Submit makes an unsaved one-time run; create makes a saved job.", "map": [["Must appear in the Jobs list and retry", "Saved job", "jobs create, then run-now"], ["One-time run, nothing saved", "Ad hoc", "jobs submit"], ["Change an existing job's full settings", "Update", "jobs reset, or update for partial change"], ["Same definition in every workspace", "Repeatability", "JSON file or bundle"]], "apply": [["\"saved so it appears in the Jobs list and retries\"", "Rules out jobs submit, which is unsaved and does not retry."], ["\"created identically ... by a release script\"", "Rules out manual recreation."]], "rule": "A saved, retrying job is created with create and started with run-now; submit is only for one-off runs.", "guide": "Create and automate ETL workloads using Lakeflow Jobs via the UI, API, and CLI."}, "eli5": "Registering a company before trading, not renting a market stall for one afternoon.", "learn": "https://docs.databricks.com/aws/en/dev-tools/cli/reference/jobs-commands", "why": ["Works, but submitted runs are not saved as a job and do not retry on failure.", "Works, but reset overwrites an existing job's settings, which does not fit creating a new one.", "Works, but manual recreation is not repeatable and breaks the release script requirement.", "Best fit: create saves the job definition and run-now starts it, so it is listed and retried."]}, {"id": "s1-a03", "type": "single", "skill": "S1 · Developing Code", "stem": "A bank's governance team wants one masking function written once, called by name from SQL in many teams' queries, with access controlled by grants and visible in lineage. The logic is a few lines of string handling. What should be created?", "options": ["A pandas UDF packaged in a wheel that each team installs on its own cluster", "A Python function in a repository that each team copies into its own pipeline code", "A PySpark UDF registered inside a shared notebook that each team runs before its queries", "A function registered in Unity Catalog, with EXECUTE granted to the consuming groups"], "answer": 3, "runner": 0, "runnerWhy": "a pandas UDF is faster per row, but it is not governed or callable by name from SQL; it wins when speed on huge volumes matters more than sharing.", "think": {"premise": "That a UDF is just code that runs in a query. Where it is registered decides who can find it, call it and be audited.", "map": [["Many teams call one function by name", "Registration scope", "Unity Catalog function"], ["Access by grants", "Governance", "EXECUTE on the function, USAGE on schema and catalog"], ["Millions of rows, numeric logic", "Speed", "Pandas UDF working on batches"], ["Logic fits one SQL expression", "Simplicity", "SQL UDF, no Python environment"]], "apply": [["\"called by name from SQL in many teams' queries\"", "Rules out notebook-scoped and copied code."], ["\"access controlled by grants and visible in lineage\"", "Only a catalog-registered function gives this."]], "rule": "Shared and governed means a Unity Catalog function; fast over big batches means a pandas UDF.", "guide": "Develop User-Defined Functions (UDFs) using Pandas, Python, and SQL, including Unity Catalog functions for the given constraints."}, "eli5": "A rule posted on the building's notice board, with a sign-in sheet, beats a rule each tenant copies onto their own wall.", "learn": "https://docs.databricks.com/aws/en/udf/unity-catalog", "why": ["Works, but a wheel on each cluster is per-cluster, ungoverned and not callable by name from SQL.", "Works, but copied code drifts between teams and has no central access control.", "Works, but a notebook-scoped UDF exists only in that session and has no grants or lineage.", "Best fit: a catalog function is callable by name, governed by EXECUTE grants and tracked in lineage."]}, {"id": "s3-01", "type": "single", "skill": "S3 · Data Manipulation", "stem": "A retailer has an orders table with billions of rows. Analysts need every order to show the customer's previous order date and the running total of that customer's spend, ordered by date, with no rows removed. Which transformation fits best?", "options": ["A GROUP BY customer with max and sum, joined back to the orders table on customer", "A Python UDF that collects each customer's orders into a list and loops through it in order", "A self join of orders to orders on customer, where the earlier date is the largest one below this order's date", "Window functions by customer ordered by date: lag for the previous date, sum for the total"], "answer": 3, "runner": 0, "runnerWhy": "aggregate then join back does produce totals, and it is right if the result should be one row per customer, but it cannot give a per-order previous date or running total.", "think": {"premise": "That every per-row comparison needs a join. A window function adds a calculation to each row over its group without collapsing rows.", "map": [["Per-row value that depends on neighbours", "Tool", "Window function with PARTITION BY and ORDER BY"], ["Result should shrink to one row per group", "Where the runner-up wins", "GROUP BY"], ["Counts higher than expected after a join", "Diagnosis", "Check key uniqueness"]], "apply": [["\"no rows removed\"", "Rules out plain GROUP BY, which collapses rows."], ["\"running total ... ordered by date\"", "An ordered window frame."]], "rule": "Keep every row and add a calculation from its neighbours: use a window function.", "guide": "Apply advanced data transformations, including window functions, joins, and aggregations, using Spark SQL and PySpark to process large datasets."}, "eli5": "A running tally on each receipt, instead of a separate summary sheet you must staple back on.", "learn": "https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-window-functions", "why": ["Works, but grouping loses the per-order detail, so neither the previous date nor a running total comes out.", "Works, but it pulls each customer's rows into one task, which skews badly and bypasses the optimizer.", "Works, but at this scale it is a costly join, and ties on date can match more than one earlier order.", "Best fit: one pass over partitioned, ordered rows keeps every order and adds both columns."]}, {"id": "s4-02", "type": "single", "skill": "S4 · Monitoring and Alerting", "stem": "A security officer needs to know which user changed the permissions on a Unity Catalog table three weeks ago, in a workspace the officer cannot open. The account admin has granted read access to the system catalog. Where should the officer look?", "options": ["The pipeline event log of the pipeline that last wrote to that table, in its update history", "The query history page of the workspace where the table is mostly used, filtered to that week", "The audit table in the system access schema, filtered by action and date", "The Spark UI of the cluster that was running when the change was made, on its event timeline"], "answer": 2, "runner": 1, "runnerWhy": "query history shows SQL statements and is useful when the change was made by a statement, but it is per workspace and may not record API-driven grants.", "think": {"premise": "That the place where the table is used also records who administered it. Administrative actions are recorded in the audit log.", "map": [["Who did what, and when", "Access audit table", "Filter by service, action and time"], ["Which tables a query read", "Lineage tables", "Query table lineage"], ["One statement's text in one workspace", "Query history", "Open that statement"]], "apply": [["\"three weeks ago\"", "Too old for a live run screen."], ["\"a workspace the officer cannot open\"", "Rules out workspace-local pages."]], "rule": "Questions about who did what across the account go to the audit table.", "guide": "Use Databricks system tables (billing, compute, access, lakeflow) for cost analysis, auditing, and workload monitoring."}, "eli5": "A building's visitor book, not the room's temperature chart.", "learn": "https://docs.databricks.com/aws/en/admin/system-tables/", "why": ["Works, but the event log shows pipeline updates and not who granted privileges.", "Works, but it is limited to one workspace and statements, so API-driven changes can be missed.", "Best fit: audit rows record the user, action and time across the account and last 395 days by default.", "Works, but the Spark UI shows compute work, not administrative actions, and expires with the cluster."]}, {"id": "s4-03", "type": "single", "skill": "S4 · Monitoring and Alerting", "stem": "An operations team wants a script that runs every hour, reads the current state of ten jobs and two pipelines, and posts a summary to a chat tool. The script runs in CI under a shared identity, not a person. What should it use?", "options": ["A browser automation script that reads the status column from the Jobs page with a saved login", "The Databricks SDK for Python with a service principal calling the Jobs and Pipelines APIs", "A query on the billing usage system table, run on a serverless SQL warehouse each hour", "A scheduled export of the Jobs UI run list that a teammate saves to a shared folder"], "answer": 1, "runner": 2, "runnerWhy": "system tables are good for history and cost, but they are not the control-plane view of current job and pipeline state.", "think": {"premise": "That any data source with run history can feed a status bot. Programs read current state through the API, CLI or SDK.", "map": [["A program reads job and pipeline state", "REST API, CLI or SDK", "Use a service principal"], ["Months of history or cost", "System tables", "Query with SQL"], ["A person checks one run", "Jobs UI", "Open the run page"]], "apply": [["\"runs every hour\"", "A repeatable program is needed."], ["\"under a shared identity, not a person\"", "Points to a service principal with the SDK."]], "rule": "Scripts read current job and pipeline state through the API, CLI or SDK under a service principal.", "guide": "Use Databricks REST APIs / CLI and SDK for monitoring and analyzing jobs and pipelines."}, "eli5": "Ask the front desk by phone instead of sending someone to read the board each hour.", "learn": "https://docs.databricks.com/aws/en/dev-tools/sdk-python", "why": ["Works, but scraping a page breaks when the layout changes and needs a user login.", "Best fit: the SDK wraps authentication and paging and a service principal avoids tying the script to one person.", "Works, but billing rows describe cost and not whether a job's latest run succeeded.", "Works, but a manual export depends on a person and cannot run on a schedule by itself."]}, {"id": "s8-01", "type": "single", "skill": "S8 · Debugging and Deploying", "stem": "A dashboard query on a SQL warehouse got much slower after a table grew. It still succeeds with no error. The engineer wants to see which step of the query takes the time and how many rows it handles. What should be opened?", "options": ["The query profile for that query, then its longest-running operators", "The Spark UI of a cluster created for the notebook that owns the dashboard", "The driver log of the warehouse, searching for exception messages", "The init script log of the compute that serves the warehouse"], "answer": 0, "runner": 1, "runnerWhy": "the Spark UI would win if the work ran on a cluster, but a warehouse query is read through its profile.", "think": {"premise": "That slowness leaves a log trail. A slow but successful query throws nothing, so the operator view is the evidence.", "map": [["Slow SQL query on a warehouse", "Query profile", "Find the top operator"], ["Slow stage in a cluster notebook", "Spark UI stages and tasks", "Compare task times"], ["Exception in a task", "Driver or executor log", "Read the stack trace"]], "apply": [["\"still succeeds with no error\"", "Logs would be empty."], ["\"which step of the query takes the time\"", "Operator-level view is needed."]], "rule": "A slow SQL query is read in its query profile, not in logs.", "guide": "Identify pertinent diagnostic information using Spark UI, cluster logs, system tables, and query profiles to troubleshoot errors."}, "eli5": "Ask the checklist for the slow step, not the complaints box.", "learn": "https://docs.databricks.com/aws/en/sql/user/queries/query-profile", "why": ["Best fit: the profile lists operators with time and rows, so the costly step is visible at once.", "Works, but the query ran on a warehouse, not on that cluster, so its stages are not there.", "Works, but the query raised no exception, so the log holds nothing about the slow step.", "Works, but init script logs show startup problems, which are unrelated to a slow query."]}, {"id": "s2-01", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "A logistics company receives about forty thousand small JSON files a day from carriers into cloud storage. A scheduled job must load only files it has not yet processed, and the carriers sometimes add a new field. Nobody wants a hand-kept list of loaded file names. Which approach fits?", "options": ["Auto Loader with a checkpoint and schema location, run on a schedule with the availableNow trigger", "A Python loop that lists the folder and keeps processed file names in a Delta control table", "A batch spark.read of the whole folder on every run, followed by a MERGE against the target table on a business key", "A Kafka topic fed by a custom forwarder, read by a streaming job with startingOffsets earliest"], "answer": 0, "runner": 2, "runnerWhy": "it is a valid batch pattern and the MERGE prevents duplicates, but it re-lists and rereads the whole folder each run; it would win for a small static folder.", "think": {"premise": "That reading a folder is a plain batch job. Auto Loader remembers which files it already processed, so each run touches only new files.", "map": [["New files keep landing in storage", "File discovery", "Auto Loader (cloudFiles) with a checkpoint"], ["Carriers add a field", "Schema drift", "Schema location with addNewColumns, or rescue to keep the schema fixed"], ["Small static folder, one-off load", "Where the runner-up wins", "Plain batch read"]], "apply": [["\"load only files it has not yet processed\"", "Needs file tracking, which Auto Loader does and a plain batch read does not."], ["\"Nobody wants a hand-kept list\"", "Rules out the control-table loop."]], "rule": "New files arriving in storage means Auto Loader; it keeps the list of processed files for you.", "guide": "Develop data ingestion pipelines to ingest a variety of data formats, including Delta Lake, Parquet, JSON, Iceberg, CSV, and Binary from diverse sources such as message buses (Kafka, Kinesis, Pub/Sub) and cloud storage."}, "eli5": "A mail clerk who ticks each letter off a list is better than one who rereads the whole mailbox every morning.", "learn": "https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/", "why": ["Best fit: Auto Loader tracks processed files itself and handles new fields through its schema location.", "Works, but you own the bookkeeping, retries and race conditions that Auto Loader already handles.", "Works, but every run lists and rereads the full folder, which gets slower as the folder grows.", "Works, but adding a message bus between storage and the job is extra moving parts for a problem files already solve."]}, {"id": "s2-03", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "A customer-master feed carries a key, an operation column (insert, update or delete) and an increasing sequence number. Events can arrive out of order across files. The target table in a Lakeflow Pipeline must show only the latest state of each customer, with deleted customers removed. What should you configure?", "options": ["AUTO CDC with KEYS, SEQUENCE BY the sequence number, a delete condition, stored as SCD type 1", "AUTO CDC with the same settings, but stored as SCD type 2 so every version is kept", "An append-only streaming table, with a view that picks the newest row per key", "A foreachBatch function that runs a MERGE using the arrival time of each micro-batch as the ordering column"], "answer": 0, "runner": 1, "runnerWhy": "type 2 is correct when history is required, and it would win if the stem asked for earlier versions; here it only adds rows nobody asked for.", "think": {"premise": "That the last row to arrive is the latest change. With out-of-order feeds, the sequence column decides the final state.", "map": [["Only current state wanted", "SCD choice", "Type 1"], ["Out-of-order events", "Ordering", "SEQUENCE BY the sequence column"], ["Stem asks for history or what it was last March", "Where the runner-up wins", "Type 2 with __START_AT and __END_AT"]], "apply": [["\"only the latest state of each customer\"", "Type 1 keeps one row per key; rules out type 2."], ["\"arrive out of order\"", "Rules out ordering by arrival time."]], "rule": "Latest state only means SCD type 1; history means type 2.", "guide": "Configure incremental CDC pipelines using Lakeflow Pipelines with Delta or Iceberg as the target table format."}, "eli5": "Keep one index card per customer and always trust the numbered date stamp, not the order the mail came in.", "learn": "https://docs.databricks.com/aws/en/ldp/cdc", "why": ["Best fit: type 1 keeps one current row per key, ordered by the sequence column, with deletes applied.", "Works, but type 2 stores every version, growing the table with history the stem did not request.", "Works, but the table keeps growing, deletes are not applied, and every reader pays for the newest-row logic.", "Works, but ordering by arrival time lets a late old event overwrite a newer one, and you code deletes yourself."]}, {"id": "s1-b03", "type": "single", "skill": "S1 · Developing Code", "stem": "A nightly Lakeflow Job has a validation task that stores the number of rejected records as a task value. A cleanup task should run only when that number is greater than zero, and should be skipped otherwise. Nothing upstream fails. What should you configure?", "options": ["A For each task whose inputs are the rejected record count and whose nested task is cleanup", "An If/else condition task comparing the task value to zero, with cleanup on the true branch", "A scheduled second job that always runs cleanup and exits early inside the notebook", "A run-if dependency on the cleanup task set to run when at least one upstream task failed"], "answer": 1, "runner": 3, "runnerWhy": "run-if dependencies react to upstream success or failure; they would win if the trigger were an upstream failure rather than a value.", "think": {"premise": "That run-if and If/else are interchangeable. Run-if looks at upstream task outcomes; If/else looks at a value you compare.", "map": [["Branch on a number a task produced", "Condition task", "If/else on the task value"], ["Branch on an upstream failure", "Dependency rule", "Run-if"], ["Repeat one task over a list", "Loop", "For each"]], "apply": [["\"greater than zero\"", "A value test, so an If/else with a numeric comparison."], ["\"Nothing upstream fails\"", "Rules out the run-if on failure."]], "rule": "A value decides with If/else; an outcome decides with run-if; a list repeats with For each.", "guide": "Create Lakeflow Jobs that use control-flow operators such as If/Else conditions and For Each loops."}, "eli5": "A gate that opens when the count is big enough, not when something broke.", "learn": "https://docs.databricks.com/aws/en/jobs/if-else", "why": ["Works, but a loop repeats a task per item, and a single count is not a list to iterate over.", "Best fit: the condition task reads the task value, and the cleanup depends only on the true outcome.", "Works, but a second job adds a separate schedule and starts compute for runs that do nothing.", "Works, but run-if on failure never fires here because nothing upstream fails."]}, {"id": "s5-03", "type": "single", "skill": "S5 · Cost and Performance", "stem": "A table of two billion rows takes a MERGE every hour that changes under one percent of its rows, yet each run rewrites most of the files it touches and takes too long. Reads are already fast. What should the team enable?", "options": ["The disk cache enabled on the worker nodes", "Deletion vectors enabled on the table to avoid rewrites", "CLUSTER BY AUTO enabled on the Delta table", "A higher shuffle partition count for MERGE"], "answer": 1, "runner": 2, "runnerWhy": "automatic clustering helps read skipping and can improve MERGE matching, but the stated problem is file rewrites, so it loses unless reads were slow.", "think": {"premise": "That every performance problem is a layout problem. Here the cost is rewriting whole files for tiny changes.", "map": [["Small changes rewrite whole files", "Write cost", "Deletion vectors"], ["Reads slow, filters skip little", "Read layout", "Liquid Clustering"], ["Same files read repeatedly", "I/O", "Disk cache"]], "apply": [["\"changes under one percent of its rows\"", "Marking rows instead of rewriting files fits."], ["\"Reads are already fast\"", "Rules out layout and caching changes."]], "rule": "Deletion vectors make row-level writes cheap; they do not make reads skip more.", "guide": "Choose the appropriate Delta optimization technique (deletion vectors, Liquid Clustering, CLUSTER BY AUTO) for a given table access pattern."}, "eli5": "Crossing out a line in a page instead of retyping the whole page.", "learn": "https://docs.databricks.com/aws/en/delta/deletion-vectors", "why": ["Works, but caching speeds repeated reads, not file rewrites during writes.", "Best fit: deletion vectors record changed rows in metadata so small changes skip a full file rewrite.", "Works, but it targets read skipping, and reads are not the problem.", "Works, but more shuffle partitions raise parallelism and make more, smaller files, not fewer rewrites."]}, {"id": "s2-05", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "A bank wants its SQL Server loan tables in Unity Catalog, refreshed incrementally from the database's change data. The team will not write extraction code, and the source database administrators agree to enable change capture. Which solution fits best?", "options": ["A Lakeflow Connect SQL Server ingestion pipeline using a Unity Catalog connection", "A third-party export job that writes CSV files for Auto Loader to pick up", "A Lakehouse Federation foreign catalog on the SQL Server instance, queried live through a connection", "A nightly Spark JDBC read of each full table, overwriting the target table"], "answer": 0, "runner": 2, "runnerWhy": "federation needs no copy and is the better choice when reads are occasional and ad hoc, but it stores nothing and hits the source on every query.", "think": {"premise": "That a connection to the database means the same thing for queries and for ingestion. Federation reads live; Lakeflow Connect copies changes incrementally.", "map": [["Incremental copy from a relational source, no code", "Tool", "Lakeflow Connect managed pipeline"], ["Source must enable change capture", "Prerequisite", "CDC or change tracking on the source"], ["Occasional live reads, no stored copy", "Where the runner-up wins", "Lakehouse Federation"]], "apply": [["\"refreshed incrementally from the database's change data\"", "Rules out the full overwrite."], ["\"will not write extraction code\"", "Rules out hand-built export jobs."]], "rule": "Incremental copy of a relational source with no code is Lakeflow Connect; live queries with no copy is federation.", "guide": "Configure CDC ingestion pipelines from relational database sources, including SQL Server, MySQL, and PostgreSQL, using Lakeflow Connect."}, "eli5": "Subscribe to the bank's daily change notices instead of photocopying the whole ledger every night.", "learn": "https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/sql-server-overview", "why": ["Best fit: the managed connector reads the change data and keeps Unity Catalog tables current without custom code.", "Works, but it adds a custom export to build and run, which the team said it would not write.", "Works, but every query hits the production database and no history or copy is kept in the lakehouse.", "Works, but it rereads every table fully each night and misses the incremental requirement."]}, {"id": "s2-06", "type": "single", "skill": "S2 · Ingestion and Acquisition", "stem": "A manufacturer wants to give a supplier read access to one Unity Catalog table. The supplier has its own Databricks workspace with Unity Catalog enabled. Both companies want access governed and audited on each side, and nobody wants to manage long-lived tokens. Which sharing approach fits?", "options": ["A scheduled export of the table as Parquet files into the supplier's bucket", "A Clean Room with both companies as collaborators and an approved notebook for joint analysis", "Open sharing with a bearer token sent to the supplier's data team", "Databricks-to-Databricks sharing with the supplier's metastore as the recipient"], "answer": 3, "runner": 2, "runnerWhy": "open sharing works for any recipient, and it would win if the supplier did not use Databricks; here it adds a token to manage.", "think": {"premise": "That sharing with an outside company always means tokens. When the recipient has a Unity Catalog workspace, D2D needs no token.", "map": [["Recipient is a Unity Catalog workspace", "Sharing mode", "D2D, governed on both sides"], ["Recipient has no Databricks", "Sharing mode", "Open sharing with token or OIDC"], ["Joint analysis, rows must stay private", "Different tool", "Clean Room"]], "apply": [["\"has its own Databricks workspace with Unity Catalog enabled\"", "Makes D2D possible."], ["\"nobody wants to manage long-lived tokens\"", "Rules out token-based open sharing."]], "rule": "Recipient on Databricks means D2D; recipient anywhere else means open sharing.", "guide": "Implement OpenSharing (D2D and Databricks-to-Open) and Clean Rooms for privacy-preserving collaboration."}, "eli5": "Hand the supplier a keycard that already belongs to their building, instead of cutting a spare key.", "learn": "https://docs.databricks.com/aws/en/delta-sharing/", "why": ["Works, but the exported copy leaves governance and goes stale as soon as it is written.", "Works, but a clean room is for joint computation on private data, which is more setup than plain read access.", "Works, but a long-lived bearer token must be issued, stored and rotated, which the stem rules out.", "Best fit: D2D needs no token, and both sides keep Unity Catalog governance and auditing."]}]};